-- 语文积累本-高中与初中实虚词词义例句（统一数据表，按实虚词一审修订）

START TRANSACTION;

UPDATE `edu_chn_word_sense` SET `status` = 0, `is_del` = 1 WHERE `id` IN (7, 28, 56, 69, 86, 100, 110, 133, 153, 170, 214, 1029, 1042);

INSERT INTO `edu_chn_word_sense`
(`id`, `word_class`, `word`, `pinyin`, `meaning`, `example`, `source`, `example_trans`, `status`, `is_del`)
VALUES
(1, 1, '劝', 'quàn', '<动>勉励，鼓励', '<b>劝</b>学', '高中必修上册｜《劝学》', '鼓励人们学习', 0, 0),
(2, 1, '疾', 'jí', '<形>劲疾，强劲，猛烈', '顺风而呼，声非加<b>疾</b>也，而闻者彰。', '高中必修上册｜《劝学》', '顺着风呼喊，声音并没有变得更加洪亮，但听的人却能听得格外清楚。', 1, 0),
(3, 1, '彰', 'zhāng', '<形>明显，清楚', '顺风而呼，声非加疾也，而闻者<b>彰</b>。', '高中必修上册｜《劝学》', '顺风呼喊，声音没有加大，但听到的人觉得清楚。', 1, 0),
(4, 1, '假', 'jiǎ', '<动>借助，利用', '<b>假</b>舆马者，非利足也，而致千里；', '高中必修上册｜《劝学》', '借助车马的人，脚并不快，却能到达千里；', 1, 0),
(5, 1, '绝', 'jué', '<动>横渡', '假舟楫者，非能水也，而<b>绝</b>江河。', '高中必修上册｜《劝学》', '借助船和桨的人，并不善于游泳，却能横渡江河。', 1, 0),
(6, 1, '积', 'jī', '<动>堆积，积累', '<b>积</b>土成山，风雨兴焉；', '高中必修上册｜《劝学》', '堆积土石成为高山，风雨就从这里兴起。', 1, 0),
(8, 1, '舍', 'shě', '<动>舍弃，放弃', '驽马十驾，功在不<b>舍</b>。', '高中必修上册｜《劝学》', '劣马连走十天，它的成功在于不放弃 。', 1, 0),
(9, 1, '兴', 'xīng', '<动>兴起', '积土成山，风雨<b>兴</b>焉；', '高中必修上册｜《劝学》', '堆积土石成为高山，风雨就从这里兴起。', 1, 0),
(10, 1, '望', 'wàng', '<动>远看，远望', '吾尝跂而<b>望</b>矣，不如登高之博见也。', '高中必修上册｜《劝学》', '我曾踮起脚跟远望，不如登高看得广。', 1, 0),
(11, 1, '知', 'zhì', '<通假>同“智”，智慧，聪明', '故木受绳则直，金就砺则利，君子博学而日参省乎己，则<b>知</b>明而行无过矣。', '高中必修上册｜《劝学》', '所以木材用墨线量过就直，刀剑等金属靠近磨刀石就锋利，君子广泛学习并且每天检查反省自己，就能智慧明达、行为没有过错。', 1, 0),
(12, 2, '而', 'ér', '<连>表转折', '青，取之于蓝，<b>而</b>青于蓝；', '高中必修上册｜《劝学》', '靛青从蓼蓝中取得，却比蓼蓝颜色更深；', 1, 0),
(13, 2, '于', 'yú', '<介>介词，从', '青，取之<b>于</b>蓝，而青<b>于</b>蓝；', '高中必修上册｜《劝学》', '靛青从蓼蓝中取得，却比蓼蓝颜色更深；', 1, 0),
(14, 2, '之', 'zhī', '<代>代词，它，指青', '青，取<b>之</b>于蓝，而青于蓝；', '高中必修上册｜《劝学》', '靛青从蓼蓝中取得，却比蓼蓝颜色更深；', 1, 0),
(15, 2, '者', 'zhě', '<助>……的人', '虽有槁暴，不复挺<b>者</b>，輮使之然也。', '高中必修上册｜《劝学》', '即使又晒干，也不会再挺直，这是火烤使它变成这样的。', 1, 0),
(16, 2, '也', 'yě', '<助>表判断，是', '虽有槁暴，不复挺者，輮使之然<b>也</b>。', '高中必修上册｜《劝学》', '即使又晒干，也不会再挺直，这是火烤使它变成这样的。', 1, 0),
(17, 1, '师', 'shī', '<意动>以……为师，意动用法', '古之学者必有<b>师</b>。', '高中必修上册｜《师说》', '古代求学的人一定有老师。', 1, 0),
(18, 1, '惑', 'huò', '<名>疑惑，疑难问题', '师者，所以传道受业解<b>惑</b>也。', '高中必修上册｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 1, 0),
(19, 1, '传', 'chuán', '<名>传授的知识', '师者，所以<b>传</b>道受业解惑也。', '高中必修上册｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 1, 0),
(20, 1, '从', 'cóng', '<动>跟随', '惑而不<b>从</b>师，其为惑也，终不解矣。', '高中必修上册｜《师说》', '有疑惑却不跟从老师学习，那些疑惑最终也不能解决。', 1, 0),
(21, 1, '贤', 'xián', '<动>超过，胜过', '是故弟子不必不如师，师不必<b>贤</b>于弟子，闻道有先后，术业有专攻，如是而已。', '高中必修上册｜《师说》', '因此学生不一定不如老师，老师也不一定比学生贤能，听闻道理有先有后，学术技艺各有专门研究，如此而已。', 1, 0),
(22, 1, '益', 'yì', '<副>更加', '是故圣<b>益</b>圣，愚<b>益</b>愚。', '高中必修上册｜《师说》', '圣人之所以圣明、愚人之所以愚昧，大概都出于这个原因吧？', 1, 0),
(23, 1, '穷', 'qióng', '<形>困窘，处境困难', NULL, '高中必修上册｜《师说》', '附件将“穷”列入《师说》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(24, 1, '通', 'tōng', '<形>通晓，明白', '李氏子蟠，年十七，好古文，六艺经传皆<b>通</b>习之，不拘于时，学于余。', '高中必修上册｜《师说》', '李家的孩子蟠，十七岁，喜欢古文，六经的经文和传文都普遍学习了，不受时俗拘束，向我学习。', 1, 0),
(25, 1, '达', 'dá', '<形>通达，得志', NULL, '高中必修上册｜《师说》', '附件将“达”列入《师说》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(26, 2, '之', 'zhī', '<助>助词，的', '古<b>之</b>学者必有师。', '高中必修上册｜《师说》', '古代求学的人一定有老师。', 1, 0),
(27, 2, '其', 'qí', '<代>代词，他的', '惑而不从师，<b>其</b>为惑也，终不解矣。', '高中必修上册｜《师说》', '有疑惑却不跟从老师学习，那些疑惑最终也不能解决。', 1, 0),
(29, 2, '于', 'yú', '<介>介词，向、对', '吾师道也，夫庸知其年之先后生<b>于</b>吾乎？', '高中必修上册｜《师说》', '我学习的是道理，哪里要了解他的年龄比我大还是小呢？', 1, 0),
(30, 2, '乎', 'hū', '<语气>表反问，吗', '生<b>乎</b>吾前，其闻道也固先<b>乎</b>吾，吾从而师之；', '高中必修上册｜《师说》', '出生在我前面的人，他懂得道理本来就比我早，我跟从他把他当作老师；', 1, 0),
(31, 2, '所', 'suǒ', '<助>与“以”组成“所以”，表示用来……的', '师者，<b>所</b>以传道受业解惑也。', '高中必修上册｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 1, 0),
(32, 2, '则', 'zé', '<连>表转折，却', '于其身也，<b>则</b>耻师焉，惑矣。', '高中必修上册｜《师说》', '对于自己，却以从师学习为可耻，真是糊涂。', 1, 0),
(33, 1, '逝', 'shì', '<动>流逝', '<b>逝</b>者如斯，而未尝往也；', '高中必修上册｜《赤壁赋》', '流逝的水像这样，却未曾真正流走；', 1, 0),
(34, 1, '盈', 'yíng', '<形>满', '<b>盈</b>虚者如彼，而卒莫消长也。', '高中必修上册｜《赤壁赋》', '月有圆缺像那样，但终究没有增减。', 1, 0),
(35, 1, '虚', 'xū', '<形>空', '浩浩乎如冯<b>虚</b>御风，而不知其所止；', '高中必修上册｜《赤壁赋》', '飘飘然像脱离尘世、独立存在，飞升成仙。', 1, 0),
(36, 1, '取', 'qǔ', '<动>取得，获得', '且夫天地之间，物各有主，苟非吾之所有，虽一毫而莫<b>取</b>。', '高中必修上册｜《赤壁赋》', '况且天地之间万物各有主人，如果不是我所有，即使一丝一毫也不能取用。', 1, 0),
(37, 1, '望', 'wàng', '<名>农历每月十五日', '壬戌之秋，七月既<b>望</b>，苏子与客泛舟游于赤壁之下。', '高中必修上册｜《赤壁赋》', '壬戌年秋，七月十六日，苏轼和友人在赤壁下泛舟游览。', 1, 0),
(38, 1, '如', 'rú', '<动>往，去', '纵一苇之所<b>如</b>，凌万顷之茫然。', '高中必修上册｜《赤壁赋》', '任凭小船漂到哪里，越过茫茫万顷的江面，浩浩荡荡仿佛凌空乘风而行，不知停在哪里；', 1, 0),
(39, 1, '绝', 'jué', '<动>断，断绝', '余音袅袅，不<b>绝</b>如缕。', '高中必修上册｜《赤壁赋》', '尾声婉转悠长，像细丝绵延不断。', 1, 0),
(40, 1, '适', 'shì', '<副>恰好', '惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭，是造物者之无尽藏也，而吾与子之所共<b>适</b>。', '高中必修上册｜《赤壁赋》', '只有江上的清风和山间的明月，耳朵听到就成为声音，眼睛看到就成为景色，取用它们没有禁令，享用它们不会竭尽，这是大自然无穷无尽的宝藏，是我和你共同享用的东西。', 1, 0),
(41, 2, '之', 'zhī', '<助>助词，的', '壬戌<b>之</b>秋，七月既望，苏子与客泛舟游于赤壁<b>之</b>下。', '高中必修上册｜《赤壁赋》', '壬戌年秋，七月十六日，苏轼和友人在赤壁下泛舟游览。', 1, 0),
(42, 2, '其', 'qí', '<代>代词，它，指月亮', '浩浩乎如冯虚御风，而不知<b>其</b>所止；', '高中必修上册｜《赤壁赋》', '飘飘然像脱离尘世、独立存在，飞升成仙。', 1, 0),
(43, 2, '而', 'ér', '<连>表转折', '浩浩乎如冯虚御风，<b>而</b>不知其所止；', '高中必修上册｜《赤壁赋》', '浩荡的样子，像是凌空乘风飞去，却不知道将停留在什么地方。', 1, 0),
(44, 2, '于', 'yú', '<介>介词，在', '壬戌之秋，七月既望，苏子与客泛舟游<b>于</b>赤壁之下。', '高中必修上册｜《赤壁赋》', '壬戌年秋，七月十六日，苏轼和友人在赤壁下泛舟游览。', 1, 0),
(45, 2, '乎', 'hū', '<语气>表疑问，吗', '浩浩<b>乎</b>如冯虚御风，而不知其所止；', '高中必修上册｜《赤壁赋》', '飘飘然像脱离尘世、独立存在，飞升成仙。', 1, 0),
(46, 2, '焉', 'yān', '<兼>兼词，于之，在那里', '少<b>焉</b>，月出于东山之上，徘徊于斗牛之间。', '高中必修上册｜《赤壁赋》', '一会儿月亮从东山升起，在斗宿牛宿之间徘徊。', 1, 0),
(47, 1, '历', 'lì', '<动>经过', '余以乾隆三十九年十二月，自京师乘风雪，<b>历</b>齐河、长清，穿泰山西北谷，越长城之限，至于泰安。', '高中必修上册｜《登泰山记》', '我在乾隆三十九年十二月，从京城乘着风雪，经过齐河、长清，穿过泰山西北的山谷，越过长城的界限，到了泰安。', 1, 0),
(48, 1, '抵', 'dǐ', '<动>到达', NULL, '高中必修上册｜《登泰山记》', '附件将“抵”列入《登泰山记》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(49, 1, '极', 'jí', '<名>尽头', '<b>极</b>天云一线异色，须臾成五采。', '高中必修上册｜《登泰山记》', '天边的云中有一线奇异的色彩，一会儿变成五彩。', 1, 0),
(50, 1, '望', 'wàng', '<动>远看，远望', '<b>望</b>晚日照城郭，汶水、徂徕如画，而半山居雾若带然。', '高中必修上册｜《登泰山记》', '远望夕阳照着城郭，汶水、徂徕山美如图画，半山停留着的雾气像一条白带。', 1, 0),
(51, 1, '始', 'shǐ', '<动>开始', '余<b>始</b>循以入，道少半，越中岭，复循西谷，遂至其巅。', '高中必修上册｜《登泰山记》', '我开始沿着中谷进入，路走不到一半，越过中岭，又沿着西谷走，于是到达山顶。', 1, 0),
(52, 1, '行', 'xíng', '<动>行走', '皇帝<b>行</b>宫在碧霞元君祠东。', '高中必修上册｜《登泰山记》', '皇帝的行宫在碧霞元君祠东边。', 1, 0),
(53, 1, '道', 'dào', '<名>道路', '四十五里，<b>道</b>皆砌石为磴，其级七千有余。', '高中必修上册｜《登泰山记》', '路程四十五里，道路都是石头砌成的台阶，台阶有七千多级。', 1, 0),
(54, 2, '之', 'zhī', '<助>助词，的', '泰山<b>之</b>阳，汶水西流；', '高中必修上册｜《登泰山记》', '泰山的南面，汶水向西流；', 1, 0),
(55, 2, '其', 'qí', '<代>代词，它，指泰山', '<b>其</b>阴，济水东流。', '高中必修上册｜《登泰山记》', '泰山的北面，济水向东流。', 1, 0),
(57, 2, '以', 'yǐ', '<介>介词，在', '余<b>以</b>乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷，越长城之限，至于泰安。', '高中必修上册｜《登泰山记》', '我在乾隆三十九年十二月，从京城乘着风雪，经过齐河、长清，穿过泰山西北的山谷，越过长城的界限，到了泰安。', 1, 0),
(58, 2, '于', 'yú', '<介>介词，在', '余以乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷，越长城之限，至<b>于</b>泰安。', '高中必修上册｜《登泰山记》', '我在乾隆三十九年十二月，从京城乘着风雪，经过齐河、长清，穿过泰山西北的山谷，越过长城的界限，到了泰安。', 1, 0),
(59, 1, '率', 'shuài', '<形>轻率，草率', '子路<b>率</b>尔而对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '子路轻率地回答：“一个有一千辆兵车的国家，夹在大国之间，又有军队侵犯它，接着发生饥荒；', 1, 0),
(60, 1, '方', 'fāng', '<名>道理；礼义', '由也为之，比及三年，可使有勇，且知<b>方</b>也。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '如果让我治理，等到三年，可以使百姓勇敢，并且懂得道义。', 1, 0),
(61, 1, '冠', 'guàn', '<名>古代男子二十岁束发加冠的礼仪，表示已成人', '”曰：“莫春者，春服既成，<b>冠</b>者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '”曾点说：“暮春三月，春衣已经穿上，成年人五六人，儿童六七人，在沂水边洗浴，在舞雩台上吹风，唱着歌回来。', 1, 0),
(62, 1, '让', 'ràng', '<动>谦让；礼让', '为国以礼，其言不<b>让</b>，是故哂之。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '治理国家要讲礼，可是他的话一点也不谦让，所以孔子笑他。', 1, 0),
(63, 1, '知', 'zhì', '<动>知道；了解', '居则曰：“不吾<b>知</b>也！”', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '平时总说：“没有人了解我！”', 1, 0),
(64, 1, '得', 'dé', '<动>获得；得到；取得。与“失”相对', NULL, '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '附件将“得”列入《子路、曾皙、冉有、公西华侍坐》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(66, 2, '以', 'yǐ', '<介>因为', '子曰：“<b>以</b>吾一日长乎尔，毋吾<b>以</b>也。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '孔子说：“不要因为我年长一些就不说了。', 1, 0),
(67, 2, '之', 'zhī', '<代>代词，这件事', '子路率尔而对曰：“千乘<b>之</b>国，摄乎大国<b>之</b>间，加<b>之</b>以师旅，因<b>之</b>以饥馑；', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '子路轻率地回答：“一个有一千辆兵车的国家，夹在大国之间，又有军队侵犯它，接着发生饥荒；', 1, 0),
(68, 2, '其', 'qí', '<代>代词，他的', '如<b>其</b>礼乐，以俟君子。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '至于礼乐教化，等待贤能的君子来做。', 1, 0),
(70, 2, '焉', 'yān', '<语气>语气助词，呢', '”对曰：“非曰能之，愿学<b>焉</b>。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '”回答：“不敢说我能做到，只愿学习。', 1, 0),
(71, 2, '乎', 'hū', '<语气>表疑问，吗', '子曰：“以吾一日长<b>乎</b>尔，毋吾以也。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '孔子说：“不要因为我年长一些就不说了。', 1, 0),
(72, 2, '则', 'zé', '<副>就', '居<b>则</b>曰：‘不吾知也！', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '你们平时总说：‘没有人了解我！', 1, 0),
(73, 1, '保', 'bǎo', '<动>安抚，安定', '<b>保</b>民而王，莫之能御也。', '高中必修下册｜《齐桓晋文之事》', '安抚百姓而称王，便没有人能抵挡他。', 1, 0),
(74, 1, '辟', 'pì', '<动>开辟', '欲<b>辟</b>土地，朝秦楚，莅中国而抚四夷也。', '高中必修下册｜《齐桓晋文之事》', '想要开辟土地，使秦楚来朝见，统治中原，安抚四方的少数民族。', 1, 0),
(75, 1, '举', 'jǔ', '<动>推及', '<b>举</b>斯心加诸彼而已。', '高中必修下册｜《齐桓晋文之事》', '把这样的心施加到别人身上罢了。', 1, 0),
(76, 1, '度', 'duó', '<动>衡量', '<b>度</b>，然后知长短。', '高中必修下册｜《齐桓晋文之事》', '用尺量，然后知道长短。', 1, 0),
(77, 1, '治', 'zhì', '<动>治理', '<b>治</b>天下可运之掌上。', '高中必修下册｜《齐桓晋文之事》', '治理天下就可以像在手掌上运转东西一样容易。', 1, 0),
(78, 1, '爱', 'ài', '<动>吝惜', '诚有百姓者，王无异于百姓之以王为<b>爱</b>也。', '高中必修下册｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(79, 1, '安', 'ān', '<动>安定，使安定', NULL, '高中必修下册｜《齐桓晋文之事》', '附件将“安”列入《齐桓晋文之事》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(80, 1, '诚', 'chéng', '<副>果真', '<b>诚</b>有百姓者，王无异于百姓之以王为爱也。', '高中必修下册｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(81, 1, '道', 'dào', '<名>王道', '然而王<b>道</b>之始也。', '高中必修下册｜《齐桓晋文之事》', '这就是王道的开端。', 1, 0),
(82, 1, '故', 'gù', '<副>所以', '<b>故</b>曰：仁者无敌。', '高中必修下册｜《齐桓晋文之事》', '所以说，施行仁政的人是无敌于天下的。大王请不要怀疑。', 1, 0),
(83, 2, '之', 'zhī', '<助>助词，的', '诚有百姓者，王无异于百姓<b>之</b>以王为爱也。', '高中必修下册｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(84, 2, '其', 'qí', '<代>代词，他的', '王若隐<b>其</b>无罪而就死地，则牛羊何择焉？', '高中必修下册｜《齐桓晋文之事》', '大王如果怜悯它没有罪却走向死地，那么牛和羊又有什么区别呢？', 1, 0),
(85, 2, '以', 'yǐ', '<介>用，拿', '诚有百姓者，王无异于百姓之<b>以</b>王为爱也。', '高中必修下册｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(87, 2, '于', 'yú', '<介>介词，比', '诚有百姓者，王无异<b>于</b>百姓之以王为爱也。', '高中必修下册｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(88, 2, '则', 'zé', '<副>就', '王若隐其无罪而就死地，<b>则</b>牛羊何择焉？', '高中必修下册｜《齐桓晋文之事》', '大王如果怜悯它没有罪却走向死地，那么牛和羊又有什么区别呢？', 1, 0),
(89, 2, '焉', 'yān', '<语气>语气助词，呢', '王若隐其无罪而就死地，则牛羊何择<b>焉</b>？', '高中必修下册｜《齐桓晋文之事》', '大王如果怜悯它没有罪却走向死地，那么牛和羊又有什么区别呢？', 1, 0),
(90, 2, '何', 'hé', '<代>什么', '齐国虽褊小，吾<b>何</b>爱一牛？', '高中必修下册｜《齐桓晋文之事》', '齐国虽然狭小，我怎么会吝惜一头牛呢？', 1, 0),
(91, 1, '解', 'jiě', '<动>分解，剖开', '庖丁为文惠君<b>解</b>牛。', '高中必修下册｜《庖丁解牛》', '厨师丁给文惠君宰牛。', 1, 0),
(92, 1, '中', 'zhòng', '<动>合乎', '手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不<b>中</b>音。', '高中必修下册｜《庖丁解牛》', '手接触的地方、肩倚靠的地方、脚踩踏的地方、膝盖顶住的地方，发出砉砉的声响，进刀时发出騞騞的声音，没有不合乎音律。', 1, 0),
(93, 1, '族', 'zú', '<名>筋骨交错的地方', '<b>族</b>庖月更刀，折也。', '高中必修下册｜《庖丁解牛》', '一般厨师一个月换一把刀，因为砍断。', 1, 0),
(94, 1, '发', 'fā', '<动>出，发出声音', '今臣之刀十九年矣，所解数千牛矣，而刀刃若新<b>发</b>于硎。', '高中必修下册｜《庖丁解牛》', '我的刀用了十九年，宰了几千头牛，刀刃好像刚从磨刀石上磨出来。', 1, 0),
(95, 1, '养', 'yǎng', '<动>保养', '吾闻庖丁之言，得<b>养</b>生焉。', '高中必修下册｜《庖丁解牛》', '我听了庖丁的话，懂得养生的道理了。', 1, 0),
(96, 1, '技', 'jì', '<名>技艺', '<b>技</b>盖至此乎？', '高中必修下册｜《庖丁解牛》', '技术怎么能高超到这种程度呢？', 1, 0),
(97, 1, '经', 'jīng', '<名>经脉', '合于《桑林》之舞，乃中《<b>经</b>首》之会。', '高中必修下册｜《庖丁解牛》', '合乎《桑林》舞蹈的节拍，也合乎《经首》乐曲的节奏。', 1, 0),
(98, 2, '之', 'zhī', '<助>助词，的', '手<b>之</b>所触，肩<b>之</b>所倚，足<b>之</b>所履，膝<b>之</b>所踦，砉然向然，奏刀騞然，莫不中音。', '高中必修下册｜《庖丁解牛》', '手接触的地方、肩倚靠的地方、脚踩踏的地方、膝盖顶住的地方，发出砉砉的声响，进刀时发出騞騞的声音，没有不合乎音律。', 1, 0),
(99, 2, '其', 'qí', '<代>代词，它，指牛', '依乎天理，批大郤，导大窾，因<b>其</b>固然，技经肯綮之未尝，而况大軱乎！', '高中必修下册｜《庖丁解牛》', '依照牛体天然的结构，击入大的缝隙，引导刀进入大的空隙，顺着牛体本来的结构，连筋骨经络都没有碰到，更何况大骨呢！', 1, 0),
(101, 2, '以', 'yǐ', '<介>因为', '方今之时，臣<b>以</b>神遇而不<b>以</b>目视，官知止而神欲行。', '高中必修下册｜《庖丁解牛》', '现在，我用精神去接触而不用眼睛看，视觉停止了而精神在运行。', 1, 0),
(102, 2, '焉', 'yān', '<兼>兼词，于之，在其中', '吾闻庖丁之言，得养生<b>焉</b>。', '高中必修下册｜《庖丁解牛》', '我听了庖丁的话，懂得养生的道理了。', 1, 0),
(103, 1, '退', 'tuì', '<使动>使……退却', '佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必<b>退</b>。', '高中必修下册｜《烛之武退秦师》', '佚之狐对郑伯说：“国家危险了，如果派烛之武去见秦君，秦军一定会撤退。', 1, 0),
(104, 1, '辞', 'cí', '<动>推辞', '<b>辞</b>曰：“臣之壮也，犹不如人；', '高中必修下册｜《烛之武退秦师》', '烛之武推辞说：“我年轻时尚且不如别人；', 1, 0),
(105, 1, '鄙', 'bǐ', '<名>边邑', '越国以<b>鄙</b>远，君知其难也，焉用亡郑以陪邻？', '高中必修下册｜《烛之武退秦师》', '越过晋国把远方的郑国作为边邑，您知道很困难，为什么要灭亡郑国来增加邻国的土地呢？', 1, 0),
(106, 1, '济', 'jì', '<动>渡过', '且君尝为晋君赐矣，许君焦、瑕，朝<b>济</b>而夕设版焉，君之所知也。', '高中必修下册｜《烛之武退秦师》', '况且您曾经给过晋君恩惠，他答应把焦、瑕给您，早晨渡河归晋，晚上就筑城防御，这是您知道的。', 1, 0),
(107, 1, '阙', 'quē', '<动>侵损，削减', '既东封郑，又欲肆其西封，若不<b>阙</b>秦，焉取之？', '高中必修下册｜《烛之武退秦师》', '既然向东把郑国作为疆界，又想扩张西部疆界，如果不损害秦国，将从哪里取得土地？', 1, 0),
(108, 1, '图', 'tú', '<动>考虑', '阙秦以利晋，唯君<b>图</b>之。', '高中必修下册｜《烛之武退秦师》', '损害秦国来使晋国获利，希望您考虑这件事。', 1, 0),
(109, 1, '亡', 'wáng', '<动>灭亡', '然郑<b>亡</b>，子亦有不利焉！', '高中必修下册｜《烛之武退秦师》', '但郑国灭亡，对您也不利啊！', 1, 0),
(111, 1, '及', 'jí', '<动>赶得上', '微夫人之力不<b>及</b>此。', '高中必修下册｜《烛之武退秦师》', '没有那个人的力量，我到不了今天。', 1, 0),
(112, 2, '之', 'zhī', '<助>助词，的', '佚<b>之</b>狐言于郑伯曰：“国危矣，若使烛<b>之</b>武见秦君，师必退。', '高中必修下册｜《烛之武退秦师》', '佚之狐对郑伯说：“国家危险了，如果派烛之武去见秦君，秦军一定会撤退。', 1, 0),
(113, 2, '其', 'qí', '<代>代词，它，指郑国', '晋侯、秦伯围郑，以<b>其</b>无礼于晋，且贰于楚也。', '高中必修下册｜《烛之武退秦师》', '晋文公和秦穆公包围郑国，因为郑国曾对晋国无礼，并且在晋、楚之间摇摆。', 1, 0),
(114, 2, '而', 'ér', '<连>表承接', '公曰：“吾不能早用子，今急<b>而</b>求子，是寡人之过也。”', '高中必修下册｜《烛之武退秦师》', '郑伯说：“我没有早点任用您，现在危急才求您，这是我的过错。”', 1, 0),
(115, 2, '以', 'yǐ', '<介>因为', '晋侯、秦伯围郑，<b>以</b>其无礼于晋，且贰于楚也。', '高中必修下册｜《烛之武退秦师》', '晋文公和秦穆公包围郑国，因为郑国曾对晋国无礼，并且在晋、楚之间摇摆。', 1, 0),
(116, 2, '于', 'yú', '<介>介词，对、向', '晋侯、秦伯围郑，以其无礼<b>于</b>晋，且贰<b>于</b>楚也。', '高中必修下册｜《烛之武退秦师》', '晋文公和秦穆公包围郑国，因为郑国曾对晋国无礼，并且在晋、楚之间摇摆。', 1, 0),
(117, 2, '焉', 'yān', '<语气>语气助词，呢', '然郑亡，子亦有不利<b>焉</b>！', '高中必修下册｜《烛之武退秦师》', '但郑国灭亡，对您也不利啊！', 1, 0),
(118, 2, '夫', 'fū', '<语气>句首语气助词', '<b>夫</b>晋，何厌之有？', '高中必修下册｜《烛之武退秦师》', '晋国哪里有满足的时候？', 1, 0),
(119, 2, '与', 'yǔ', '<介>和', '秦伯说，<b>与</b>郑人盟。', '高中必修下册｜《烛之武退秦师》', '秦穆公很高兴，和郑国结盟。', 1, 0),
(120, 1, '军', 'jūn', '<动>驻军，驻扎', '沛公<b>军</b>霸上，未得与项羽相见。', '高中必修下册｜《鸿门宴》', '沛公的军队驻扎在霸上，还没有能够和项羽相见。', 1, 0),
(121, 1, '倍', 'bèi', '<通假>同“背”，背叛', '愿伯具言臣之不敢<b>倍</b>德也。', '高中必修下册｜《鸿门宴》', '希望您详细说明我不敢背叛恩德。', 1, 0),
(122, 1, '谢', 'xiè', '<动>道歉', '旦日不可不蚤自来<b>谢</b>项王。', '高中必修下册｜《鸿门宴》', '明天早晨不能不早些亲自来向项王道歉。', 1, 0),
(123, 1, '坐', 'zuò', '<动>坐下', '项王、项伯东向<b>坐</b>；', '高中必修下册｜《鸿门宴》', '项王、项伯面向东坐，亚父面向南坐。', 1, 0),
(124, 1, '辞', 'cí', '<动>推辞', '臣死且不避，卮酒安足<b>辞</b>！', '高中必修下册｜《鸿门宴》', '我连死都不躲避，一杯酒哪里值得推辞！', 1, 0),
(125, 1, '得', 'dé', '<动>能够', '沛公军霸上，未<b>得</b>与项羽相见。', '高中必修下册｜《鸿门宴》', '沛公的军队驻扎在霸上，还没有能够和项羽相见。', 1, 0),
(126, 1, '度', 'duó', '<动>估计', '<b>度</b>我至军中，公乃入。', '高中必修下册｜《鸿门宴》', '估计我已经回到军营，您才进去。', 1, 0),
(127, 1, '如', 'rú', '<动>及，比得上', '杀人<b>如</b>不能举，刑人<b>如</b>恐不胜。', '高中必修下册｜《鸿门宴》', '杀人唯恐不能杀尽，给人施刑唯恐不能用尽。', 1, 0),
(128, 1, '胜', 'shèng', '<动>尽，完', '杀人如不能举，刑人如恐不<b>胜</b>。', '高中必修下册｜《鸿门宴》', '杀人唯恐不能杀尽，给人施刑唯恐不能用尽。', 1, 0),
(129, 1, '数', 'shuò', '<副>多次', '范增<b>数</b>目项王，举所佩玉玦以示之者三。', '高中必修下册｜《鸿门宴》', '范增多次向项王使眼色，再三举起他佩戴的玉玦给项王看。', 1, 0),
(130, 1, '王', 'wàng', '<使动>称王，让……称王', '范增数目项<b>王</b>，举所佩玉玦以示之者三。', '高中必修下册｜《鸿门宴》', '范增多次向项王使眼色，再三举起他佩戴的玉玦给项王看。', 1, 0),
(131, 2, '之', 'zhī', '<动>动词，到、往', '秦时与臣游，项伯杀人，臣活<b>之</b>。', '高中必修下册｜《鸿门宴》', '秦朝时他和我交往，项伯杀了人，我使他活了下来。', 1, 0),
(132, 2, '其', 'qí', '<代>代词，他的', NULL, '高中必修下册｜《鸿门宴》', '附件将“其”列入《鸿门宴》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(134, 2, '以', 'yǐ', '<介>把', '项伯乃夜驰之沛公军，私见张良，具告<b>以</b>事。', '高中必修下册｜《鸿门宴》', '项伯于是连夜骑马赶到沛公的军营，私下会见张良，把事情全部告诉了他。', 1, 0),
(135, 2, '于', 'yú', '<介>介词，在', NULL, '高中必修下册｜《鸿门宴》', '附件将“于”列入《鸿门宴》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(136, 2, '为', 'wéi', '<介>替，给', '窃<b>为</b>大王不取也。', '高中必修下册｜《鸿门宴》', '我私下认为大王不应该采取这种做法。', 1, 0),
(137, 2, '者', 'zhě', '<助>……的人', '范增数目项王，举所佩玉玦以示之<b>者</b>三。', '高中必修下册｜《鸿门宴》', '范增多次向项王使眼色，再三举起他佩戴的玉玦给项王看。', 1, 0),
(138, 2, '也', 'yě', '<助>表判断', '愿伯具言臣之不敢倍德<b>也</b>。', '高中必修下册｜《鸿门宴》', '希望您详细说明我不敢背叛恩德。', 1, 0),
(139, 2, '则', 'zé', '<副>就', NULL, '高中必修下册｜《鸿门宴》', '附件将“则”列入《鸿门宴》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(140, 2, '乃', 'nǎi', '<副>于是，就', '项伯<b>乃</b>夜驰之沛公军，私见张良，具告以事。', '高中必修下册｜《鸿门宴》', '项伯于是连夜骑马赶到沛公的军营，私下会见张良，把事情全部告诉了他。', 1, 0),
(141, 1, '征', 'zhēng', '<动>征收', '宣德间，宫中尚促织之戏，岁<b>征</b>民间。', '高中必修下册｜《促织》', '宣德年间，皇宫中盛行斗蟋蟀的游戏，每年从民间征收蟋蟀。', 1, 0),
(142, 1, '岁', 'suì', '<名>年', '宣德间，宫中尚促织之戏，<b>岁</b>征民间。', '高中必修下册｜《促织》', '宣德年间，皇宫中盛行斗蟋蟀的游戏，每年从民间征收蟋蟀。', 1, 0),
(143, 1, '业', 'yè', '<副>已经', NULL, '高中必修下册｜《促织》', '附件将“业”列入《促织》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(144, 1, '累', 'lěi', '<副>连续，多次', NULL, '高中必修下册｜《促织》', '附件将“累”列入《促织》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(145, 1, '窥', 'kuī', '<动>偷偷地看', '<b>窥</b>父不在，窃发盆。', '高中必修下册｜《促织》', '他偷偷看见父亲不在，便悄悄打开了盆子。', 1, 0),
(146, 1, '捷', 'jié', '<形>敏捷，迅速', NULL, '高中必修下册｜《促织》', '附件将“捷”列入《促织》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(147, 1, '索', 'suǒ', '<动>寻找', NULL, '高中必修下册｜《促织》', '附件将“索”列入《促织》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(148, 1, '遂', 'suì', '<副>于是', '<b>遂</b>为猾胥报充里正役。', '高中必修下册｜《促织》', '于是被奸猾的胥吏报上去充任里正的差事。', 1, 0),
(149, 1, '顾', 'gù', '<副>但，不过', '<b>顾</b>念蓄劣物终无所用。', '高中必修下册｜《促织》', '只是想到养着劣等的蟋蟀终究没有什么用处。', 1, 0),
(150, 1, '闻', 'wén', '<动>听到', '<b>闻</b>妻言，如被冰雪。', '高中必修下册｜《促织》', '听到妻子的话，好像被冰雪覆盖一样。', 1, 0),
(151, 2, '之', 'zhī', '<助>助词，的', '宣德间，宫中尚促织<b>之</b>戏，岁征民间。', '高中必修下册｜《促织》', '宣德年间，皇宫中盛行斗蟋蟀的游戏，每年从民间征收蟋蟀。', 1, 0),
(152, 2, '其', 'qí', '<代>代词，他的', NULL, '高中必修下册｜《促织》', '附件将“其”列入《促织》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(154, 2, '以', 'yǐ', '<介>把', NULL, '高中必修下册｜《促织》', '附件将“以”列入《促织》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(155, 2, '于', 'yú', '<介>介词，在', '问者爇香<b>于</b>鼎，再拜。', '高中必修下册｜《促织》', '询问的人在香炉中点燃香，拜了两拜。', 1, 0),
(156, 2, '则', 'zé', '<副>就', '<b>则</b>虫集冠上，力叮不释。', '高中必修下册｜《促织》', '蟋蟀就落在帽子上，用力叮住不放。', 1, 0),
(157, 2, '乃', 'nǎi', '<副>于是，就', '<b>乃</b>赏成，献诸抚军。', '高中必修下册｜《促织》', '于是赏赐成名，把蟋蟀献给巡抚。', 1, 0),
(158, 1, '逐', 'zhú', '<动>驱逐', '臣闻吏议<b>逐</b>客，窃以为过矣。', '高中必修下册｜《谏逐客书》', '我听说官吏们在商议驱逐客卿，私下认为这是错误的。', 1, 0),
(159, 1, '广', 'guǎng', '<使动>使……广泛，扩大', '臣闻地<b>广</b>者粟多，国大者人众，兵强则士勇。', '高中必修下册｜《谏逐客书》', '我听说土地广阔粮食就多，国家强大人口就多，兵力强盛士气就勇。', 1, 0),
(160, 1, '纳', 'nà', '<动>接受', NULL, '高中必修下册｜《谏逐客书》', '附件将“纳”列入《谏逐客书》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(161, 1, '任', 'rèn', '<动>任用', NULL, '高中必修下册｜《谏逐客书》', '附件将“任”列入《谏逐客书》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(162, 1, '施', 'shī', '<动>施行', '惠王用张仪之计，拔三川之地，西并巴、蜀，北收上郡，南取汉中，包九夷，制鄢郢，东据成皋之险，割膏腴之壤，遂散六国之从，使之西面事秦，功<b>施</b>到今。', '高中必修下册｜《谏逐客书》', '秦惠王采用张仪的计策，攻取三川，向西兼并巴蜀，向北收取上郡，向南夺取汉中，包围九夷，控制鄢郢，向东占据成皋险要，割取肥沃土地，瓦解六国合纵，使六国向西侍奉秦国，功业延续至今。', 1, 0),
(163, 1, '举', 'jǔ', '<副>所有', '孝公用商鞅之法，移风易俗，民以殷盛，国以富强，百姓乐用，诸侯亲服，获楚、魏之师，<b>举</b>地千里，至今治强。', '高中必修下册｜《谏逐客书》', '秦孝公采用商鞅变法，改变风俗，百姓富足，国家强盛，诸侯亲近归服，打败楚魏军队，夺取千里土地，至今政治安定强大。', 1, 0),
(165, 1, '治', 'zhì', '<动>治理', '孝公用商鞅之法，移风易俗，民以殷盛，国以富强，百姓乐用，诸侯亲服，获楚、魏之师，举地千里，至今<b>治</b>强。', '高中必修下册｜《谏逐客书》', '秦孝公采用商鞅变法，改变风俗，百姓富足，国家强盛，诸侯亲近归服，打败楚魏军队，夺取千里土地，至今政治安定强大。', 1, 0),
(166, 1, '因', 'yīn', '<动>依靠，凭借', NULL, '高中必修下册｜《谏逐客书》', '附件将“因”列入《谏逐客书》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(167, 2, '之', 'zhī', '<助>助词，的', '此五子者，不产于秦，而穆公用<b>之</b>，并国二十，遂霸西戎。', '高中必修下册｜《谏逐客书》', '这五个人不出生在秦国，秦穆公任用他们，兼并二十个国家，于是称霸西戎。', 1, 0),
(168, 2, '其', 'qí', '<代>代词，它的', '是以泰山不让土壤，故能成<b>其</b>大；', '高中必修下册｜《谏逐客书》', '泰山不拒绝土壤，所以能成就高大；', 1, 0),
(169, 2, '以', 'yǐ', '<介>用，凭借', '臣闻吏议逐客，窃<b>以</b>为过矣。', '高中必修下册｜《谏逐客书》', '我听说官吏们在商议驱逐客卿，私下认为这是错误的。', 1, 0),
(171, 2, '于', 'yú', '<介>介词，从', '昔穆公求士，西取由余<b>于</b>戎，东得百里奚<b>于</b>宛，迎蹇叔<b>于</b>宋，来丕豹、公孙支<b>于</b>晋。', '高中必修下册｜《谏逐客书》', '过去秦穆公寻求贤士，西面从戎地得到由余，东面从宛地得到百里奚，从宋国迎来蹇叔，从晋国招来丕豹、公孙支。', 1, 0),
(172, 2, '则', 'zé', '<副>就', '必秦国之所生然后可，<b>则</b>是夜光之璧不饰朝廷，犀象之器不玩好，郑、卫之女不充后宫，而骏良駃騠不实外厩，江南金锡不为用，西蜀丹青不为采。', '高中必修下册｜《谏逐客书》', '如果一定要秦国出产的才可以，那么夜光璧不能装饰朝廷，犀角象牙器不能成为玩物，郑卫美女不能充实后宫，良马不能放入马厩，江南金锡不能使用，西蜀丹青不能采纳。', 1, 0),
(173, 2, '因', 'yīn', '<连>因为', NULL, '高中必修下册｜《谏逐客书》', '附件将“因”列入《谏逐客书》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(174, 1, '固', 'gù', '<使动>使……稳固', '臣闻求木之长者，必<b>固</b>其根本；', '高中必修下册｜《谏太宗十思疏》', '我听说想要树木长得高大，一定要使它的根牢固；', 1, 0),
(175, 1, '崇', 'chóng', '<动>推崇，尊重', '人君当神器之重，居域中之大，将<b>崇</b>极天之峻，永保无疆之休。', '高中必修下册｜《谏太宗十思疏》', '国君掌握帝王的重权，处在天地中心的至尊地位，将使皇位崇高如天、永远保持无边的美好。', 1, 0),
(176, 1, '戒', 'jiè', '<动>告诫', '不念居安思危，<b>戒</b>奢以俭，德不处其厚，情不胜其欲，斯亦伐根以求木茂，塞源而欲流长者也。', '高中必修下册｜《谏太宗十思疏》', '如果不居安思危、戒奢侈行节俭，道德不能保持厚重、性情不能克制欲望，这也像砍断根却求树木茂盛、堵塞源头却想水流长远。', 1, 0),
(177, 1, '安', 'ān', '<形>安定；安稳；安宁；安全', '思国之<b>安</b>者，必积其德义。', '高中必修下册｜《谏太宗十思疏》', '想要国家安定，一定要积累道德仁义。', 1, 0),
(178, 1, '诚', 'chéng', '<副>确实', '盖在殷忧必竭<b>诚</b>以待下，既得志则纵情以傲物。', '高中必修下册｜《谏太宗十思疏》', '大概在忧虑时必定竭尽诚意对待臣民，得志以后就放纵情感傲视他人。', 1, 0),
(179, 1, '求', 'qiú', '<动>追求', '臣闻<b>求</b>木之长者，必固其根本；', '高中必修下册｜《谏太宗十思疏》', '我听说想要树木长得高大，一定要使它的根牢固；', 1, 0),
(180, 1, '因', 'yīn', '<动>顺着，依靠', '诚能见可欲则思知足以自戒，将有作则思知止以安人，念高危则思谦冲而自牧，惧满溢则思江海下百川，乐盘游则思三驱以为度，忧懈怠则思慎始而敬终，虑壅蔽则思虚心以纳下，想谗邪则思正身以黜恶，恩所加则思无<b>因</b>喜以谬赏，罚所及则思无<b>因</b>怒而滥刑。', '高中必修下册｜《谏太宗十思疏》', '果真见到想得到的东西就想到知足来自我警戒，将要兴建什么就想到适可而止使百姓安定，想到帝位高危就想到谦虚自我修养，害怕骄傲自满就想到江海处在百川之下，喜爱打猎游乐就想到三驱为度，担心懈怠就想到慎始慎终，忧虑受蒙蔽就想到虚心采纳下属意见，想到有谗邪就想到端正自己来贬黜奸恶，施加恩惠就想到不要因一时高兴而错误奖赏，施加刑罚就想到不要因一时愤怒而滥用刑法。', 1, 0),
(181, 1, '终', 'zhōng', '<副>最终', '有善始者实繁，能克<b>终</b>者盖寡。', '高中必修下册｜《谏太宗十思疏》', '开头做得好的实在很多，能够坚持到底的却很少。', 1, 0),
(182, 2, '之', 'zhī', '<助>助词，的', '臣闻求木<b>之</b>长者，必固其根本；', '高中必修下册｜《谏太宗十思疏》', '我听说想要树木长得高大，一定要使它的根牢固；', 1, 0),
(183, 2, '其', 'qí', '<代>代词，他的', '臣闻求木之长者，必固<b>其</b>根本；', '高中必修下册｜《谏太宗十思疏》', '我听说想要树木长得高大，一定要使它的根牢固；', 1, 0),
(184, 2, '而', 'ér', '<连>表转折', '源不深<b>而</b>望流之远，根不固<b>而</b>求木之长，德不厚<b>而</b>思治之理，臣虽下愚，知其不可，<b>而</b>况于明哲乎！', '高中必修下册｜《谏太宗十思疏》', '源头不深却希望水流得远，根基不牢却要求树木长高，道德不深厚却想理好国家', 1, 0),
(185, 2, '以', 'yǐ', '<连>来，表目的', '不念居安思危，戒奢<b>以</b>俭，德不处其厚，情不胜其欲，斯亦伐根<b>以</b>求木茂，塞源而欲流长者也。', '高中必修下册｜《谏太宗十思疏》', '如果不居安思危、戒奢侈行节俭，道德不能保持厚重、性情不能克制欲望，这也像砍断根却求树木茂盛、堵塞源头却想水流长远。', 1, 0),
(186, 2, '则', 'zé', '<副>就', '盖在殷忧必竭诚以待下，既得志<b>则</b>纵情以傲物。', '高中必修下册｜《谏太宗十思疏》', '大概在忧虑时必定竭尽诚意对待臣民，得志以后就放纵情感傲视他人。', 1, 0),
(187, 2, '夫', 'fū', '<语气>句首语气助词', NULL, '高中必修下册｜《谏太宗十思疏》', '附件将“夫”列入《谏太宗十思疏》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(188, 2, '焉', 'yān', '<语气>语气助词，了', NULL, '高中必修下册｜《谏太宗十思疏》', '附件将“焉”列入《谏太宗十思疏》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(189, 1, '辩', 'biàn', '<通假>同“辨”，区别', NULL, '高中必修下册｜《答司马谏议书》', '附件将“辩”列入《答司马谏议书》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(190, 1, '固', 'gù', '<副>本来', '至于怨诽之多，则<b>固</b>前知其如此也。', '高中必修下册｜《答司马谏议书》', '至于怨恨诽谤很多，本来就预料到会这样。', 1, 0),
(191, 1, '执', 'zhí', '<动>坚持', NULL, '高中必修下册｜《答司马谏议书》', '附件将“执”列入《答司马谏议书》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(192, 1, '辟', 'pì', '<动>批驳', '<b>辟</b>邪说，难壬人，不为拒谏。', '高中必修下册｜《答司马谏议书》', '批驳错误言论，排斥奸佞小人，不是拒绝劝谏。', 1, 0),
(193, 1, '度', 'duó', '<动>考虑', '某则以为受命于人主，议法<b>度</b>而修之于朝廷，以授之于有司，不为侵官；', '高中必修下册｜《答司马谏议书》', '我却认为，接受皇帝命令，在朝廷上议订法令制度并加以修正，交给有关部门执行，不是侵夺官职；', 1, 0),
(194, 1, '任', 'rèn', '<动>任用', '无由会晤，不<b>任</b>区区向往之至。', '高中必修下册｜《答司马谏议书》', '没有机会见面，内心不胜仰慕至极。', 1, 0),
(195, 1, '事', 'shì', '<动>办事，做事', '某启：昨日蒙教，窃以为与君实游处相好之日久，而议<b>事</b>每不合，所操之术多异故也。', '高中必修下册｜《答司马谏议书》', '昨天承蒙您赐教，我私下认为和您相交友好已经很久，但议论政事常常不合，是因为我们所持的政治主张大多不同。', 1, 0),
(196, 1, '理', 'lǐ', '<名>道理', '盖儒者所争，尤在于名实，名实已明，而天下之<b>理</b>得矣。', '高中必修下册｜《答司马谏议书》', '读书人所争辩的，尤其在于名义和事实，名义和事实明确了，天下的道理也就清楚了。', 1, 0),
(197, 2, '之', 'zhī', '<助>助词，的', '某启：昨日蒙教，窃以为与君实游处相好<b>之</b>日久，而议事每不合，所操<b>之</b>术多异故也。', '高中必修下册｜《答司马谏议书》', '昨天承蒙您赐教，我私下认为和您相交友好已经很久，但议论政事常常不合，是因为我们所持的政治主张大多不同。', 1, 0),
(198, 2, '其', 'qí', '<代>代词，那些', '至于怨诽之多，则固前知<b>其</b>如此也。', '高中必修下册｜《答司马谏议书》', '至于怨恨诽谤很多，本来就预料到会这样。', 1, 0),
(199, 2, '而', 'ér', '<连>表转折', '昨日蒙教，窃以为与君实游处相好之日久，<b>而</b>议事每不合，所操之术多异故也。', '高中必修下册｜《答司马谏议书》', '昨天承蒙您赐教，我私下认为和您相交友好已经很久，但议论政事常常不合，是因为我们所持的政治主张大多不同。', 1, 0),
(200, 2, '以', 'yǐ', '<介>因为', '某启：昨日蒙教，窃<b>以</b>为与君实游处相好之日久，而议事每不合，所操之术多异故也。', '高中必修下册｜《答司马谏议书》', '昨天承蒙您赐教，我私下认为和您相交友好已经很久，但议论政事常常不合，是因为我们所持的政治主张大多不同。', 1, 0),
(201, 2, '于', 'yú', '<介>介词，对、向', '重念蒙君实视遇厚，<b>于</b>反复不宜卤莽，故今具道所以，冀君实或见恕也。', '高中必修下册｜《答司马谏议书》', '又考虑到您对我看待优厚，书信往来不应草率，因此现在详细说明事情的原委，希望您或许能够宽恕我。', 1, 0),
(202, 2, '则', 'zé', '<副>就', '某<b>则</b>以为受命于人主，议法度而修之于朝廷，以授之于有司，不为侵官；', '高中必修下册｜《答司马谏议书》', '我却认为，接受皇帝命令，在朝廷上议订法令制度并加以修正，交给有关部门执行，不是侵夺官职；', 1, 0),
(203, 2, '为', 'wéi', '<介>替，给', '某启：昨日蒙教，窃以<b>为</b>与君实游处相好之日久，而议事每不合，所操之术多异故也。', '高中必修下册｜《答司马谏议书》', '昨天承蒙您赐教，我私下认为和您相交友好已经很久，但议论政事常常不合，是因为我们所持的政治主张大多不同。', 1, 0),
(204, 1, '毕', 'bì', '<动>完结，灭亡', '六王<b>毕</b>，四海一；', '高中必修下册｜《阿房宫赋》', '六国灭亡，天下统一；', 1, 0),
(205, 1, '覆', 'fù', '<动>覆盖', '<b>覆</b>压三百余里，隔离天日。', '高中必修下册｜《阿房宫赋》', '覆盖三百多里，隔断了天空和阳光。', 1, 0),
(206, 1, '鉴', 'jiàn', '<动>借鉴', '后人哀而不<b>鉴</b>之，亦使后人而复哀后人也。', '高中必修下册｜《阿房宫赋》', '后人如果哀叹却不吸取教训，也会使更后的人再为后人哀叹了。', 1, 0),
(207, 1, '尽', 'jìn', '<动>竭尽', '一肌一容，<b>尽</b>态极妍，缦立远视，而望幸焉；', '高中必修下册｜《阿房宫赋》', '每一处肌肤、每一种容貌，都极尽娇媚，久久站立远望，等待皇帝宠幸；', 1, 0),
(208, 1, '取', 'qǔ', '<动>夺取', '奈何<b>取</b>之尽锱铢，用之如泥沙？', '高中必修下册｜《阿房宫赋》', '为什么搜刮百姓一丝一毫，用起来却像泥沙？', 1, 0),
(209, 1, '奢', 'shē', '<动>奢侈', '秦爱纷<b>奢</b>，人亦念其家。', '高中必修下册｜《阿房宫赋》', '秦人喜爱奢侈，百姓也顾念自己的家。', 1, 0),
(210, 1, '藏', 'cáng', '<名>收藏的珍宝', '燕赵之收<b>藏</b>，韩魏之经营，齐楚之精英，几世几年，剽掠其人，倚叠如山。', '高中必修下册｜《阿房宫赋》', '燕赵收藏的珠宝、韩魏经营的珍宝、齐楚保存的精华，经过几代几年，从百姓那里掠夺而来，堆积如山。', 1, 0),
(211, 1, '极', 'jí', '<动>极尽', '一肌一容，尽态<b>极</b>妍，缦立远视，而望幸焉；', '高中必修下册｜《阿房宫赋》', '每一处肌肤、每一种容貌，都极尽娇媚，久久站立远望，等待皇帝宠幸；', 1, 0),
(212, 2, '之', 'zhī', '<助>助词，的', '一日<b>之</b>内，一宫<b>之</b>间，而气候不齐。', '高中必修下册｜《阿房宫赋》', '同一天、同一座宫殿，气候却不相同。', 1, 0),
(213, 2, '其', 'qí', '<代>代词，它，指阿房宫', '盘盘焉，囷囷焉，蜂房水涡，矗不知<b>其</b>几千万落。', '高中必修下册｜《阿房宫赋》', '盘旋曲折，像蜂房、水涡，耸立着不知有几千万座。', 1, 0),
(215, 2, '以', 'yǐ', '<介>用，凭借', '使六国各爱其人，则足<b>以</b>拒秦；', '高中必修下册｜《阿房宫赋》', '假使六国各自爱护百姓，就足以抵抗秦国；', 1, 0),
(216, 2, '于', 'yú', '<介>比', '妃嫔媵嫱，王子皇孙，辞楼下殿，辇来<b>于</b>秦；', '高中必修下册｜《阿房宫赋》', '妃嫔、宫女、王子皇孙，辞别楼阁殿堂，乘辇来到秦国；', 1, 0),
(217, 2, '焉', 'yān', '<语气>语气助词，呢', '盘盘<b>焉</b>，囷囷<b>焉</b>，蜂房水涡，矗不知其几千万落。', '高中必修下册｜《阿房宫赋》', '盘旋曲折，像蜂房、水涡，耸立着不知有几千万座。', 1, 0),
(218, 2, '夫', 'fū', '<语气>句首语气助词', '栋梁之材，多于南亩之农<b>夫</b>；', '高中必修下册｜《阿房宫赋》', '柱梁上的木料比田地里的农夫还多；', 1, 0),
(219, 2, '者', 'zhě', '<助>……的人', '有不得见<b>者</b>，三十六年。', '高中必修下册｜《阿房宫赋》', '有的宫女三十六年也没有被召见。', 1, 0),
(220, 1, '弊', 'bì', '<名>弊病', '六国破灭，非兵不利，战不善，<b>弊</b>在赂秦。', '高中必修下册｜《六国论》', '六国灭亡，不是兵器不锋利、仗打不好，弊病在于贿赂秦国。', 1, 0),
(221, 1, '赂', 'lù', '<名>贿赂', '六国破灭，非兵不利，战不善，弊在<b>赂</b>秦。', '高中必修下册｜《六国论》', '六国灭亡，不是兵器不锋利、仗打不好，弊病在于贿赂秦国。', 1, 0),
(222, 1, '亏', 'kuī', '<使动>使……亏损', '赂秦而力<b>亏</b>，破灭之道也。', '高中必修下册｜《六国论》', '贿赂秦国使自己的力量亏损，这是灭亡的道路。', 1, 0),
(223, 1, '殆', 'dài', '<副>几乎', '且燕赵处秦革灭<b>殆</b>尽之际，可谓智力孤危，战败而亡，诚不得已。', '高中必修下册｜《六国论》', '齐国不曾贿赂秦国，最终也随着五国迁灭，为什么？', 1, 0),
(224, 1, '弥', 'mí', '<副>更加', '然则诸侯之地有限，暴秦之欲无厌，奉之<b>弥</b>繁，侵之愈急。', '高中必修下册｜《六国论》', '诸侯土地有限，暴秦欲望没有满足，送给秦国越多，秦国侵犯越急。', 1, 0),
(225, 1, '愈', 'yù', '<副>更加', '然则诸侯之地有限，暴秦之欲无厌，奉之弥繁，侵之<b>愈</b>急。', '高中必修下册｜《六国论》', '诸侯土地有限，暴秦欲望没有满足，送给秦国越多，秦国侵犯越急。', 1, 0),
(226, 1, '继', 'jì', '<副>随着，接着', '齐人未尝赂秦，终<b>继</b>五国迁灭，何哉？', '高中必修下册｜《六国论》', '齐国不曾贿赂秦国，最终也随着五国迁灭，为什么？', 1, 0),
(227, 1, '故', 'gù', '<副>所以', '<b>故</b>曰：弊在赂秦也。', '高中必修下册｜《六国论》', '所以说，弊病在于贿赂秦国。', 1, 0),
(228, 1, '固', 'gù', '<副>本来', '则秦之所大欲，诸侯之所大患，<b>固</b>不在战矣。', '高中必修下册｜《六国论》', '秦国最大的欲望、诸侯最大的祸患，本来不在战争。', 1, 0),
(229, 1, '得', 'dé', '<动>获得；得到；取得。与“失”相对', '秦以攻取之外，小则获邑，大则<b>得</b>城。', '高中必修下册｜《六国论》', '秦国用攻战取得土地以外，小的得到邑镇，大的得到城池。', 1, 0),
(230, 2, '之', 'zhī', '<助>助词，的', '赂秦而力亏，破灭<b>之</b>道也。', '高中必修下册｜《六国论》', '贿赂秦国使自己的力量亏损，这是灭亡的道路。', 1, 0),
(231, 2, '其', 'qí', '<代>代词，他们的', '较秦之所得，与战胜而得者，<b>其</b>实百倍；', '高中必修下册｜《六国论》', '比较秦国贿赂所得和战胜所得，实际多百倍；', 1, 0),
(232, 2, '而', 'ér', '<连>表因果', '赂秦<b>而</b>力亏，破灭之道也。', '高中必修下册｜《六国论》', '贿赂秦国使自己的力量亏损，这是灭亡的道路。', 1, 0),
(233, 2, '以', 'yǐ', '<介>用，拿', '曰：不赂者<b>以</b>赂者丧，盖失强援，不能独完。', '高中必修下册｜《六国论》', '回答：不贿赂秦国的国家因为贿赂秦国的国家而灭亡，是因为失去了强大的援助，不能独自保全。', 1, 0),
(234, 2, '于', 'yú', '<介>比', '至<b>于</b>颠覆，理固宜然。', '高中必修下册｜《六国论》', '最终覆亡，按道理本来就应当如此。', 1, 0),
(235, 2, '则', 'zé', '<副>就', '秦以攻取之外，小<b>则</b>获邑，大<b>则</b>得城。', '高中必修下册｜《六国论》', '秦国用攻战取得土地以外，小的得到邑镇，大的得到城池。', 1, 0),
(236, 2, '焉', 'yān', '<语气>语气助词，了', '至丹以荆卿为计，始速祸<b>焉</b>。', '高中必修下册｜《六国论》', '赵国曾五次与秦作战，两次失败、三次胜利；', 1, 0),
(237, 2, '且', 'qiě', '<助>况且', '<b>且</b>燕赵处秦革灭殆尽之际，可谓智力孤危，战败而亡，诚不得已。', '高中必修下册｜《六国论》', '齐国不曾贿赂秦国，最终也随着五国迁灭，为什么？', 1, 0),
(1001, 1, '骤', 'zhòu', '<动>急', '俄而雪<b>骤</b>。', '七年级上册｜《咏雪》', '不一会儿，雪下得急了。', 1, 0),
(1002, 1, '若', 'ruò', '<动>如，比得上', '未<b>若</b>柳絮因风起。', '七年级上册｜《咏雪》', '不如比作柳絮乘风飞舞。', 1, 0),
(1003, 1, '拟', 'nǐ', '<动>相比', '撒盐空中差可<b>拟</b>。', '七年级上册｜《咏雪》', '把盐撒在空中大体可以相比。', 1, 0),
(1004, 2, '之', 'zhī', '<助>用于人名，无实义（“王凝之”）', '即公大兄无奕女，左将军王凝<b>之</b>妻也。', '七年级上册｜《咏雪》', '她就是谢太傅哥哥的长女，左将军王凝之的妻子。', 1, 0),
(1005, 1, '期', 'qī', '<动>约定', '陈太丘与友<b>期</b>行，<b>期</b>日中。', '七年级上册｜《陈太丘与友期行》', '陈太丘和朋友约定一同出行，约定的时间是正午。', 1, 0),
(1006, 1, '去', 'qù', '<动>离开', '太丘舍<b>去</b>，<b>去</b>后乃至。', '七年级上册｜《陈太丘与友期行》', '陈太丘离开以后，朋友才到。', 1, 0),
(1007, 1, '委', 'wěi', '<动>舍弃', '与人期行，相<b>委</b>而去。', '七年级上册｜《陈太丘与友期行》', '和别人约好一同出行，却丢下别人离开。', 1, 0),
(1008, 1, '引', 'yǐn', '<动>拉，牵拉', '友人惭，下车<b>引</b>之。', '七年级上册｜《陈太丘与友期行》', '朋友感到惭愧，下车拉元方。', 1, 0),
(1009, 1, '顾', 'gù', '<动>回头看', '元方入门不<b>顾</b>。', '七年级上册｜《陈太丘与友期行》', '元方走进家门，没有回头看他。', 1, 0),
(1010, 2, '乃', 'nǎi', '<副>才', '去后<b>乃</b>至。', '七年级上册｜《陈太丘与友期行》', '陈太丘离开以后朋友才到。', 1, 0),
(1011, 2, '之', 'zhī', '<代>代词，他，指元方', '下车引<b>之</b>。', '七年级上册｜《陈太丘与友期行》', '下车拉元方。', 1, 0),
(1012, 1, '愠', 'yùn', '<动>生气，恼怒', '人不知而不<b>愠</b>。', '七年级上册｜《论语十二章》', '别人不了解我，我却不生气。', 1, 0),
(1013, 1, '省', 'xǐng', '<动>反省', '吾日三<b>省</b>吾身。', '七年级上册｜《论语十二章》', '我每天多次反省自己。', 1, 0),
(1014, 1, '罔', 'wǎng', '<动>迷惑，感到迷茫', '学而不思则<b>罔</b>。', '七年级上册｜《论语十二章》', '只学习却不思考，就会感到迷茫。', 1, 0),
(1015, 1, '殆', 'dài', '<动>疑惑', '思而不学则<b>殆</b>。', '七年级上册｜《论语十二章》', '只思考却不学习，就会有疑惑。', 1, 0),
(1016, 2, '而', 'ér', '<连>表转折', '人不知<b>而</b>不愠。', '七年级上册｜《论语十二章》', '别人不了解我，我却不生气。', 1, 0),
(1017, 2, '而', 'ér', '<连>表承接', '温故<b>而</b>知新。', '七年级上册｜《论语十二章》', '温习学过的知识，可以得到新的理解和体会。', 1, 0),
(1018, 2, '之', 'zhī', '<代>代词，指学过的知识', '学而时习<b>之</b>。', '七年级上册｜《论语十二章》', '学习了知识，然后按时温习它。', 1, 0),
