(1264, 1, '绝', 'jué', '<形>隔绝的；封闭的', '率妻子邑人来此<b>绝</b>境。', '八年级下册｜《桃花源记》', '带领妻子儿女和同乡来到这个与世隔绝的地方。', 0, 0),
(1265, 1, '兴', 'xīng', '<动>兴办，兴建', '越明年，政通人和，百废具<b>兴</b>。', '九年级上册｜《岳阳楼记》', '到了第二年，政事顺利百姓和乐，所有荒废的事业全都兴办起来 。', 0, 0),
(1266, 2, '而', 'ér', '<连>表修饰', '吾尝终日<b>而</b>思矣。', '高中必修上册｜《劝学》', '我曾经整天地冥思苦想。', 0, 0),
(1267, 2, '而', 'ér', '<连>表修饰', '吾尝跂<b>而</b>望矣。', '高中必修上册｜《劝学》', '我曾经踮起脚后跟向远处看。', 0, 0),
(1268, 2, '而', 'ér', '<连>表修饰', '面山<b>而</b>居。', '高中必修上册｜《愚公移山》', '面对着大山居住。', 0, 0),
(1269, 2, '而', 'ér', '<连>表承接', '日出<b>而</b>林霏开，云归<b>而</b>岩穴暝。', '九年级上册｜《醉翁亭记》', '太阳升起，树林里的雾气散开；云雾聚拢，山谷就显得昏暗了。', 0, 0),
(1270, 2, '而', 'ér', '<连>表并列', '蟹六跪<b>而</b>二螯。', '高中必修上册｜《劝学》', '螃蟹有六条腿，还有两只大钳子。', 0, 0),
(1271, 2, '而', 'ér', '<连>表并列', '则知明<b>而</b>行无过矣。', '高中必修上册｜《劝学》', '那么就智慧明达，行为没有过错了。', 0, 0),
(1272, 2, '而', 'ér', '<连>表并列', '侣鱼虾<b>而</b>友麋鹿。', '高中必修上册｜《赤壁赋》', '以鱼虾为伴，以麋鹿为友。', 0, 0),
(1273, 2, '而', 'ér', '<连>表并列', '泉香<b>而</b>酒洌。', '九年级上册｜《醉翁亭记》', '泉水香甜，酒水清醇。', 0, 0),
(1274, 2, '而', 'ér', '<连>表并列', '中峨冠<b>而</b>多髯者为东坡。', '八年级下册｜《核舟记》', '中间那个戴着高高的帽子、长着浓密胡须的人是苏东坡。', 0, 0),
(1275, 2, '而', 'ér', '<连>表并列', '博学<b>而</b>笃志。', '七年级上册｜《论语十二章》', '广泛学习并且坚定志向。', 0, 0),
(1276, 2, '而', 'ér', '<连>表并列', '然后知生于忧患<b>而</b>死于安乐也。', '八年级上册｜《生于忧患，死于安乐》', '这样就知道，忧患可以使人生存，安逸享乐会使人灭亡。', 0, 0),
(1277, 2, '而', 'ér', '<连>表递进', '君子博学<b>而</b>日参省乎己，则知明而行无过矣。', '高中必修上册｜《劝学》', '君子广泛学习并且每天检查反省自己，就能智慧明达，行为没有过错。', 0, 0),
(1829, 1, '方', 'fāng', '<名>方形，与“圆”相对', '形若土狗，梅花翅，<b>方</b>首，长颈。', '高中必修下册｜《促织》', '（它）形状像土狗，有梅花翅，方头，长脖子。', 1, 0),
(1830, 1, '方', 'fāng', '<形>正直', '<b>方</b>正之不容也。', '高中选择性必修中册｜《屈原列传》', '正直的人不被容纳。', 1, 0),
(1831, 1, '方', 'fāng', '<名>方向；方位', '不知东<b>方</b>之既白。', '高中必修上册｜《赤壁赋》', '不知不觉东方已经发白。', 1, 0),
(1832, 1, '方', 'fāng', '<名>区域；地方', '有朋自远<b>方</b>来，不亦乐乎。', '七年级上册｜《论语十二章》', '有志同道合的人从远方来，不也是很快乐吗？', 1, 0),
(1833, 1, '方', 'fāng', '<名>方圆；周围', '<b>方</b>宅十余亩，草屋八九间。', '高中必修上册｜《归园田居（其一）》', '住宅四周有十多亩地，草屋有八九间。', 1, 0),
(1834, 1, '方', 'fāng', '<介>当；在', '故<b>方</b>其盛也，举天下之豪杰。', '高中选择性必修中册｜《五代史伶官传序》', '所以当他强盛时，全天下的豪杰，没有人能和他抗争。', 1, 0),
(1835, 1, '冠', 'guān', '<名>帽子', '新沐者必弹<b>冠</b>。', '高中选择性必修中册｜《屈原列传》', '刚洗过头的人要弹去帽子上的尘土。', 1, 0),
(1836, 1, '冠', 'guān', '<名>鸟类头顶上突出的肉或翎毛', '旋见鸡伸颈摆扑，临视，则虫集<b>冠</b>上，力叮不释。', '高中必修下册｜《促织》', '不一会儿，只见鸡伸长脖子扑腾，仔细一看，蟋蟀落在鸡冠上，用力叮住不放。', 1, 0),
(1837, 1, '让', 'ràng', '<动>推辞；拒绝', '是以太山不<b>让</b>土壤，故能成其大。', '高中必修下册｜《谏逐客书》', '因此泰山不拒绝土壤，所以能成就它的高大。', 1, 0),
(1838, 1, '得', 'dé', '<形>得意；满足', '当其欣于所遇，暂<b>得</b>于己，快然自足。', '高中选择性必修下册｜《兰亭集序》', '当他们对所接触的事物感到高兴，一时感到自得，感到快乐和满足。', 1, 0),
(1839, 1, '得', 'dé', '<助>表示动作完成或补充说明结果', '十三学<b>得</b>琵琶成，名属教坊第一部。', '高中必修上册｜《琵琶行并序》', '十三岁学会弹琵琶，名字列在教坊第一部。', 1, 0),
(1840, 1, '得', 'dé', '<动>实现；达到', '既<b>得</b>志则纵情以傲物。', '高中必修下册｜《谏太宗十思疏》', '得志以后就放纵情感傲视他人。', 1, 0),
(1841, 1, '安', 'ān', '<形>安定；安稳；安宁；安全', '审容膝之易<b>安</b>。', '高中选择性必修下册｜《归去来兮辞并序》', '深知仅能容下双膝的小屋容易使人安适。', 1, 0),
(1842, 1, '安', 'ān', '<形>安适；安逸', '然后知生于忧患，而死于<b>安</b>乐也。', '八年级上册｜《生于忧患，死于安乐》', '这样以后就知道忧患使人谋求生存，安逸享乐使人死亡。', 1, 0),
(1843, 1, '安', 'ān', '<形>安适；安逸', '予出官二年，恬然自<b>安</b>。', '高中必修上册｜《琵琶行并序》', '我被贬出京城两年，心境安然自得。', 1, 0)
ON DUPLICATE KEY UPDATE
`word_class` = VALUES(`word_class`),
`word` = VALUES(`word`),
`pinyin` = VALUES(`pinyin`),
`meaning` = VALUES(`meaning`),
`example` = VALUES(`example`),
`source` = VALUES(`source`),
`example_trans` = VALUES(`example_trans`),
`status` = VALUES(`status`),
`is_del` = VALUES(`is_del`);

-- 当前有效词义统一上架
UPDATE `edu_chn_word_sense` SET `status` = 1 WHERE `is_del` = 0;

COMMIT;

-- 选择性必修实虚词补充：仅追加，不覆盖已有审核记录。
START TRANSACTION;

INSERT INTO `edu_chn_word_sense`
(`id`, `word_class`, `word`, `pinyin`, `meaning`, `example`, `source`, `example_trans`, `status`, `is_del`)
VALUES
(1278, 1, '知', 'zhī', '<动>知道，懂得', '<b>知</b>之者不如好之者，好之者不如乐之者。', '高中选择性必修上册｜《论语十二章》', '知道学习的人比不上爱好学习的人，爱好学习的人比不上以学习为快乐的人。', 0, 0),
(1279, 1, '齐', 'qí', '<动>看齐，向……看齐', '见贤思<b>齐</b>焉，见不贤而内自省也。', '高中选择性必修上册｜《论语十二章》', '看见贤人就想要向他看齐，看见不贤的人就要在内心自我反省。', 0, 0),
(1280, 1, '事', 'shì', '<动>做，处理', '敏于<b>事</b>而慎于言，就有道而正焉。', '高中选择性必修上册｜《论语十二章》', '做事勤勉，说话谨慎，到有道德有学问的人那里去匡正自己。', 0, 0),
(1281, 1, '归', 'guī', '<动>归依，归附', '一日克己复礼，天下<b>归</b>仁焉。', '高中选择性必修上册｜《论语十二章》', '一旦克制自己，使言语行动都合乎礼，天下就会归依仁德。', 0, 0),
(1282, 1, '敏', 'mǐn', '<形>勤勉，奋勉', '<b>敏</b>于事而慎于言，就有道而正焉。', '高中选择性必修上册｜《论语十二章》', '做事勤勉，说话谨慎，到有道德有学问的人那里去匡正自己。', 0, 0),
(1283, 2, '而', 'ér', '<连>表承接', '学<b>而</b>时习之，不亦说乎？', '高中选择性必修上册｜《论语十二章》', '学习了知识，然后按时温习它，不是很愉快吗？', 0, 0),
(1284, 2, '其', 'qí', '<代>代词，他们的', '择<b>其</b>善者而从之，<b>其</b>不善者而改之。', '高中选择性必修上册｜《论语十二章》', '选择他们的优点来学习，发现他们的缺点就对照着改正自己。', 0, 0),
(1285, 2, '于', 'yú', '<介>对，对于', '不义而富且贵，<b>于</b>我如浮云。', '高中选择性必修上册｜《论语十二章》', '用不正当的手段得来的富贵，对于我来说就像天上的浮云。', 0, 0),
(1286, 2, '焉', 'yān', '<兼>兼词，于之，在其中', '三人行，必有我师<b>焉</b>。', '高中选择性必修上册｜《论语十二章》', '几个人一起走，其中一定有可以做我的老师的人。', 0, 0),
(1287, 1, '明', 'míng', '<动>彰明，发扬', '在<b>明</b><b>明</b>德，在亲民，在止于至善。', '高中选择性必修上册｜《大学之道》', '在于彰明美德，在于亲近爱护民众，在于达到道德修养的最高境界。', 0, 0),
(1288, 1, '止', 'zhǐ', '<动>达到', '在明明德，在亲民，在<b>止</b>于至善。', '高中选择性必修上册｜《大学之道》', '在于彰明美德，在于亲近爱护民众，在于达到道德修养的最高境界。', 0, 0),
(1289, 1, '致', 'zhì', '<动>推究，获得', '<b>致</b>知在格物。', '高中选择性必修上册｜《大学之道》', '推究事物的原理而获得知识。', 0, 0),
(1290, 1, '格', 'gé', '<动>推究，探究', '致知在<b>格</b>物。', '高中选择性必修上册｜《大学之道》', '推究事物的原理而获得知识。', 0, 0),
(1291, 2, '之', 'zhī', '<助>的', '大学<b>之</b>道，在明明德。', '高中选择性必修上册｜《大学之道》', '大学的宗旨在于彰明美德。', 0, 0),
(1292, 2, '而', 'ér', '<连>表承接', '知止<b>而</b>后有定，定<b>而</b>后能静。', '高中选择性必修上册｜《大学之道》', '知道应达到的境界才能志向坚定，志向坚定才能心情安静。', 0, 0),
(1293, 2, '其', 'qí', '<代>代词，他所……的', '其所厚者薄，而其所薄者厚，未之有也。', '高中选择性必修上册｜《大学之道》', '所看重的反而薄待，所轻视的反而厚待，这样的事情是没有的。', 0, 0),
(1294, 1, '故', 'gù', '<连>所以', '<b>故</b>有之以为利，无之以为用。', '高中选择性必修上册｜《老子四章》', '所以，有了车毂中间的空处才能发挥车的作用；没有它，车就无法使用。', 0, 0),
(1295, 1, '举', 'jǔ', '<动>举起，提出', NULL, '高中选择性必修上册｜《老子四章》', NULL, 0, 0),
(1296, 1, '克', 'kè', '<动>能够，克服', NULL, '高中选择性必修上册｜《老子四章》', NULL, 0, 0),
(1297, 1, '复', 'fù', '<动>返回，复归', '常德不离，<b>复</b>归于婴儿。', '高中选择性必修上册｜《老子四章》', '永恒的德性不离失，复归到婴儿般纯真的状态。', 0, 0),
(1298, 2, '而', 'ér', '<连>表转折，却', '生<b>而</b>不有，为而不恃，长而不宰，是谓玄德。', '高中选择性必修上册｜《老子四章》', '生养万物却不据为己有，帮助万物却不自恃有功，成就万物却不主宰它们，这就是深厚的德。', 0, 0),
(1299, 2, '之', 'zhī', '<助>用于主谓之间，取消句子独立性', '天下皆知美<b>之</b>为美，斯恶已。', '高中选择性必修上册｜《老子四章》', '天下人都知道美之所以为美，丑就产生了。', 0, 0),
(1300, 2, '其', 'qí', '<代>代词，它的', '<b>其</b>安易持，<b>其</b>未兆易谋。', '高中选择性必修上册｜《老子四章》', '局面安定时容易维持，事情没有显露迹象时容易谋划。', 0, 0),
(1301, 1, '属', 'zhǔ', '<动>撰写，连缀', '屈平<b>属</b>草稿未定，上官大夫见而欲夺之。', '高中选择性必修中册｜《屈原列传》', '屈原撰写的草稿还没有定稿，上官大夫看见了就想夺取过来。', 0, 0),
(1302, 1, '志', 'zhì', '<动>记载', '博闻强<b>志</b>，明于治乱，娴于辞令。', '高中选择性必修中册｜《屈原列传》', '见闻广博，记忆力强，明白国家治乱的道理，熟悉外交辞令。', 0, 0),
(1303, 1, '害', 'hài', '<动>嫉妒，损害', '争宠而心<b>害</b>其能。', '高中选择性必修中册｜《屈原列传》', '争夺宠爱而心里嫉妒他的才能。', 0, 0),
(1304, 1, '迁', 'qiān', '<动>放逐，流放', '顷襄王怒而<b>迁</b>之。', '高中选择性必修中册｜《屈原列传》', '顷襄王发怒，把他放逐了。', 0, 0),
(1305, 1, '闻', 'wén', '<动>听闻，见闻', '博<b>闻</b>强志，明于治乱，娴于辞令。', '高中选择性必修中册｜《屈原列传》', '见闻广博，记忆力强，明白国家治乱的道理，熟悉外交辞令。', 0, 0),
(1306, 1, '致', 'zhì', '<动>招致，招来', NULL, '高中选择性必修中册｜《屈原列传》', NULL, 0, 0),
(1307, 1, '见', 'jiàn', '<被动>被，表被动', '信而<b>见</b>疑，忠而被谤，能无怨乎？', '高中选择性必修中册｜《屈原列传》', '诚信却被怀疑，忠贞却被诽谤，能没有怨恨吗？', 0, 0),
(1308, 2, '而', 'ér', '<连>表因果，因而', '屈平疾王听之不聪也，谗谄之蔽明也，邪曲之害公也，方正之不容也，故忧愁幽思<b>而</b>作《离骚》。', '高中选择性必修中册｜《屈原列传》', '屈原痛心于楚怀王听信谗言、不明辨是非，邪曲小人损害公正，正直的人不被容纳，因此忧愁深思，创作了《离骚》。', 0, 0),
(1309, 2, '之', 'zhī', '<代>代词，他，指屈原', '上官大夫见而欲夺<b>之</b>，屈平不与。', '高中选择性必修中册｜《屈原列传》', '上官大夫看见了想要夺取它，屈原不给。', 0, 0),
(1310, 2, '其', 'qí', '<代>代词，他的', '<b>其</b>文约，<b>其</b>辞微，<b>其</b>志洁，<b>其</b>行廉。', '高中选择性必修中册｜《屈原列传》', '他的文章简约，他的文辞含蓄，他的志趣高洁，他的品行正直。', 0, 0),
(1311, 2, '以', 'yǐ', '<介>凭借', '<b>以</b>一仪而当汉中地，臣请往如楚。', '高中选择性必修中册｜《屈原列传》', '凭张仪一个人就抵得上汉中一带的土地，请让我到楚国去。', 0, 0),
(1312, 1, '固', 'gù', '<形>险固，坚固', '据崤函之<b>固</b>，拥雍州之地。', '高中选择性必修中册｜《过秦论》', '凭借崤山和函谷关的险固，拥有雍州的土地。', 0, 0),
(1313, 1, '务', 'wù', '<动>致力于，从事', '内立法度，<b>务</b>耕织，修守战之具。', '高中选择性必修中册｜《过秦论》', '对内建立法规制度，致力于耕作纺织，修造防守和作战的器械。', 0, 0),
(1314, 1, '修', 'xiū', '<动>修造，整治', '内立法度，务耕织，<b>修</b>守战之具。', '高中选择性必修中册｜《过秦论》', '对内建立法规制度，致力于耕作纺织，修造防守和作战的器械。', 0, 0),
(1315, 1, '爱', 'ài', '<动>爱护，吝惜', '不<b>爱</b>珍器重宝肥饶之地，以致天下之士。', '高中选择性必修中册｜《过秦论》', '不吝惜珍贵器物、重宝和肥沃富饶的土地，来招致天下的士人。', 0, 0),
(1316, 1, '致', 'zhì', '<动>招致，招来', '于是从散约败，争割地而赂秦，以<b>致</b>天下之士。', '高中选择性必修中册｜《过秦论》', '于是合纵解散、盟约破裂，争着割让土地贿赂秦国，用来招致天下的士人。', 0, 0),
(1317, 1, '亡', 'wáng', '<动>逃亡的人', '追<b>亡</b>逐北，伏尸百万，流血漂橹。', '高中选择性必修中册｜《过秦论》', '追逐逃亡的败兵，倒下的尸体有百万，流淌的血可以漂浮盾牌。', 0, 0),
(1318, 1, '乘', 'chéng', '<介>趁着，凭借', '因利<b>乘</b>便，宰割天下，分裂山河。', '高中选择性必修中册｜《过秦论》', '凭借有利的形势，割取天下，分割山河。', 0, 0),
(1319, 1, '举', 'jǔ', '<动>攻取，占领', '南取汉中，西<b>举</b>巴蜀，东割膏腴之地，北收要害之郡。', '高中选择性必修中册｜《过秦论》', '向南攻取汉中，向西攻取巴蜀，向东割取肥沃的土地，向北占领险要的郡县。', 0, 0),
(1320, 2, '以', 'yǐ', '<介>凭借', '<b>以</b>十倍之地，百万之众，叩关而攻秦。', '高中选择性必修中册｜《过秦论》', '凭借十倍于秦的土地、百万军队，攻打函谷关进攻秦国。', 0, 0),
(1321, 2, '而', 'ér', '<连>表因果，因而', '赂秦<b>而</b>力亏，破灭之道也。', '高中选择性必修中册｜《过秦论》', '贿赂秦国使自己的力量亏损，这是灭亡的道路。', 0, 0),
(1322, 2, '之', 'zhī', '<助>的', '会盟而谋弱秦，不爱珍器重宝肥饶<b>之</b>地，以致天下之士。', '高中选择性必修中册｜《过秦论》', '诸侯举行盟会谋划削弱秦国，不吝惜珍贵器物、重宝和肥沃的土地，来招致天下的士人。', 0, 0),
(1323, 2, '因', 'yīn', '<介>凭借，趁着', '<b>因</b>利乘便，宰割天下，分裂山河。', '高中选择性必修中册｜《过秦论》', '凭借有利的形势，割取天下，分割山河。', 0, 0),
(1324, 1, '原', 'yuán', '<动>推究根本', '<b>原</b>庄宗之所以得天下，与其所以失之者，可以知之矣。', '高中选择性必修中册｜《五代史伶官传序》', '推究庄宗取得天下的原因，和他失去天下的原因，就可以明白这个道理了。', 0, 0),
(1325, 1, '负', 'fù', '<动>背着', '<b>负</b>而前驱，及凯旋而纳之。', '高中选择性必修中册｜《五代史伶官传序》', '背着箭走在前面，等到凯旋时把箭收藏在太庙。', 0, 0),
(1326, 1, '告', 'gào', '<动>祭告，告知', '则遣从事以一少牢<b>告</b>庙，请其矢。', '高中选择性必修中册｜《五代史伶官传序》', '就派遣属官用猪羊各一头祭告祖庙，请出那三支箭。', 0, 0),
(1327, 1, '抑', 'yì', '<连>还是，或者', '<b>抑</b>本其成败之迹，而皆自于人欤？', '高中选择性必修中册｜《五代史伶官传序》', '还是推究他成功失败的事迹，都由于人为呢？', 0, 0),
(1328, 1, '举', 'jǔ', '<副>全，所有', '故方其盛也，<b>举</b>天下之豪杰，莫能与之争。', '高中选择性必修中册｜《五代史伶官传序》', '所以当他强盛时，全天下的豪杰，没有人能和他抗争。', 0, 0),
(1329, 2, '而', 'ér', '<连>表承接', '世言晋王之将终也，以三矢赐庄宗<b>而</b>告之曰。', '高中选择性必修中册｜《五代史伶官传序》', '世人传说晋王将要去世时，把三支箭赐给庄宗并告诉他说。', 0, 0),
(1330, 2, '其', 'qí', '<代>代词，他的', '<b>其</b>意气之盛，可谓壮哉！', '高中选择性必修中册｜《五代史伶官传序》', '他的意气是多么豪迈，可以说是雄壮啊！', 0, 0),
(1331, 2, '乃', 'nǎi', '<代>代词，你的', '尔其无忘<b>乃</b>父之志！', '高中选择性必修中册｜《五代史伶官传序》', '你一定不要忘记你父亲的志向。', 0, 0),
(1332, 2, '以', 'yǐ', '<介>用，拿', '方其系燕父子<b>以</b>组，函梁君臣之首。', '高中选择性必修中册｜《五代史伶官传序》', '当他用丝带捆绑燕王父子，用木匣装着梁国君臣的首级。', 0, 0),
(1333, 1, '除', 'chú', '<动>授予官职', '寻蒙国恩，<b>除</b>臣洗马。', '高中选择性必修下册｜《陈情表》', '不久又蒙受国恩，授予我太子洗马的官职。', 0, 0),
(1334, 1, '拜', 'bài', '<动>授官，任命', '诏书特下，<b>拜</b>臣郎中。', '高中选择性必修下册｜《陈情表》', '诏书特地下达，任命我为郎中。', 0, 0),
(1335, 1, '闵', 'mǐn', '<通假>同“悯”，忧患', '臣以险衅，夙遭<b>闵</b>凶。', '高中选择性必修下册｜《陈情表》', '我因为命运不好，早年遭遇不幸。', 0, 0),
(1336, 1, '鲜', 'xiǎn', '<副>少', '既无伯叔，终<b>鲜</b>兄弟。', '高中选择性必修下册｜《陈情表》', '既没有伯叔，也没有兄弟。', 0, 0),
(1337, 1, '逮', 'dài', '<介>及，等到', '<b>逮</b>奉圣朝，沐浴清化。', '高中选择性必修下册｜《陈情表》', '等到奉行晋朝的圣旨，受到清明的教化。', 0, 0),
(1338, 1, '笃', 'dǔ', '<形>病重', '则刘病日<b>笃</b>。', '高中选择性必修下册｜《陈情表》', '祖母刘氏的病一天比一天严重。', 0, 0),
(1339, 2, '以', 'yǐ', '<介>因为', '臣<b>以</b>险衅，夙遭闵凶。', '高中选择性必修下册｜《陈情表》', '我因为命运不好，早年遭遇不幸。', 0, 0),
(1340, 2, '而', 'ér', '<连>表承接', NULL, '高中选择性必修下册｜《陈情表》', NULL, 0, 0),
(1341, 2, '之', 'zhī', '<助>的', '是臣尽节于陛下<b>之</b>日长。', '高中选择性必修下册｜《陈情表》', '这就是我向陛下尽忠尽节的日子长。', 0, 0),
(1342, 2, '且', 'qiě', '<连>况且', '<b>且</b>臣少仕伪朝，历职郎署。', '高中选择性必修下册｜《陈情表》', '况且我年轻时曾在伪朝做官，历任郎官。', 0, 0),
(1343, 1, '归', 'guī', '<动>女子出嫁', '后五年，吾妻来<b>归</b>。', '高中选择性必修下册｜《项脊轩志》', '过了五年，我的妻子嫁到我家来。', 0, 0),
(1344, 1, '凡', 'fán', '<副>总共，一共', NULL, '高中选择性必修下册｜《项脊轩志》', NULL, 0, 0),
(1345, 1, '再', 'zài', '<副>两次', NULL, '高中选择性必修下册｜《项脊轩志》', NULL, 0, 0),
(1346, 1, '顾', 'gù', '<动>回头看', '每移案，<b>顾</b>视无可置者。', '高中选择性必修下册｜《项脊轩志》', '每次移动书桌，回头看看没有可以安置的地方。', 0, 0),
(1347, 1, '过', 'guò', '<动>超过', '日<b>过</b>午已昏，余叩门扉曰：“吾妻来归。”', '高中选择性必修下册｜《项脊轩志》', '太阳已经过了中午，屋里已经昏暗了，我敲着门说：“我的妻子嫁过来了。”', 0, 0),
(1348, 1, '殆', 'dài', '<副>大概，恐怕', '<b>殆</b>有神护者。', '高中选择性必修下册｜《项脊轩志》', '大概是有神灵在保护吧。', 0, 0),
(1349, 2, '而', 'ér', '<连>表转折，却', '借书满架，偃仰啸歌，冥然兀坐，万籁有声；<b>而</b>庭有枇杷树，吾妻死之年所手植也。', '高中选择性必修下册｜《项脊轩志》', '借来的书摆满书架，我时而俯仰时而长啸歌唱，静默地独自端坐，万物的声音都能听到；庭院里有一棵枇杷树，是我妻子去世那年亲手种的。', 0, 0),
(1350, 2, '之', 'zhī', '<助>的', '先是，庭有枇杷树，吾妻死<b>之</b>年所手植也。', '高中选择性必修下册｜《项脊轩志》', '这以前，庭院里有一棵枇杷树，是我妻子去世那年亲手种的。', 0, 0),
(1351, 2, '其', 'qí', '<代>代词，那、后来', '<b>其</b>后六年，吾妻死；<b>其</b>后二年，余久卧病无聊。', '高中选择性必修下册｜《项脊轩志》', '又过了六年，我的妻子去世；又过了两年，我长久卧病无聊。', 0, 0),
(1352, 1, '修', 'xiū', '<形>高，高长', '此地有崇山峻岭，茂林<b>修</b>竹。', '高中选择性必修下册｜《兰亭集序》', '这里有高峻的山岭、高大的树林和修长的竹子。', 0, 0),
(1353, 1, '次', 'cì', '<名>旁边，水边', '列坐其<b>次</b>。', '高中选择性必修下册｜《兰亭集序》', '大家排列坐在曲水旁边。', 0, 0),
(1354, 1, '期', 'qī', '<动>至，及', '况修短随化，终<b>期</b>于尽！', '高中选择性必修下册｜《兰亭集序》', '何况人的寿命长短听凭造化，最终归结于消灭。', 0, 0),
(1355, 1, '致', 'zhì', '<名>情趣，情致', '虽世殊事异，所以兴怀，其<b>致</b>一也。', '高中选择性必修下册｜《兰亭集序》', '虽然时代不同、事情不同，但人们产生感慨的原因和情趣是一样的。', 0, 0),
(1356, 1, '信', 'xìn', '<副>确实，实在', '<b>信</b>可乐也。', '高中选择性必修下册｜《兰亭集序》', '确实值得快乐啊。', 0, 0),
(1357, 2, '之', 'zhī', '<助>的', '会于会稽山阴<b>之</b>兰亭，修禊事也。', '高中选择性必修下册｜《兰亭集序》', '在会稽山阴的兰亭聚会，举行修禊这种活动。', 0, 0),
(1358, 2, '而', 'ér', '<连>表承接', NULL, '高中选择性必修下册｜《兰亭集序》', NULL, 0, 0),
(1359, 2, '其', 'qí', '<代>代词，他们，指人们', '当<b>其</b>欣于所遇，暂得于己，快然自足，不知老之将至。', '高中选择性必修下册｜《兰亭集序》', '当他们对所接触的事物感到高兴，一时感到自得，感到快乐和满足，竟不知道老年将要到来。', 0, 0),
(1360, 2, '以', 'yǐ', '<介>把', '引<b>以</b>为流觞曲水，列坐其次。', '高中选择性必修下册｜《兰亭集序》', '把水引来作为漂流酒杯的曲水，大家排列坐在曲水旁边。', 0, 0),
(1361, 1, '谏', 'jiàn', '<动>挽回，劝止', '悟已往之不<b>谏</b>，知来者之可追。', '高中选择性必修下册｜《归去来兮辞并序》', '认识到过去的事情已经无法挽回，知道未来的日子还可以补救。', 0, 0),
(1362, 1, '追', 'zhuī', '<动>补救，挽救', '悟已往之不谏，知来者之可<b>追</b>。', '高中选择性必修下册｜《归去来兮辞并序》', '认识到过去的事情已经无法挽回，知道未来的日子还可以补救。', 0, 0),
(1363, 1, '行', 'xíng', '<动>行走', NULL, '高中选择性必修下册｜《归去来兮辞并序》', NULL, 0, 0),
