-- 高三常考虚词文档例句补充（仅追加）
START TRANSACTION;
INSERT INTO `edu_chn_word_sense`
(`id`, `word_class`, `word`, `pinyin`, `meaning`, `example`, `source`, `example_trans`, `status`, `is_del`)
VALUES
(1388, 2, '而', 'ér', '<连>表并列；又', '蟹六跪<b>而</b>二螯，非蛇鳝之穴无可寄者', '高中必修上册｜《劝学》', NULL, 0, 0),
(1389, 2, '而', 'ér', '<连>表并列；又', '剑阁峥嵘<b>而</b>崔嵬，一夫当关，万夫莫开', '高中常考虚词｜《蜀道难》', NULL, 0, 0),
(1390, 2, '而', 'ér', '<连>表递进；并且；而且', '君子博学<b>而</b>日参省乎己', '高中必修上册｜《劝学》', NULL, 0, 0),
(1391, 2, '而', 'ér', '<连>表递进；并且；而且', '楚怀王贪<b>而</b>信张仪，遂绝齐', '高中选择性必修中册｜《屈原列传》', NULL, 0, 0),
(1392, 2, '而', 'ér', '<连>表承接；就；接着', '置之地，拔剑撞<b>而</b>破之', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1393, 2, '而', 'ér', '<连>表承接；就；接着', '人非生<b>而</b>知之者，孰能无惑', '高中必修上册｜《师说》', NULL, 0, 0),
(1394, 2, '而', 'ér', '<连>表转折；但是；却', '有如此之势，<b>而</b>为秦人积威之所劫', '高中必修下册｜《六国论》', NULL, 0, 0),
(1395, 2, '而', 'ér', '<连>表假设；如果；假如', '诸君<b>而</b>有意，瞻予马首可也。', '高中常考虚词｜《冯婉贞》', NULL, 0, 0),
(1396, 2, '而', 'ér', '<连>表假设；如果；假如', '死<b>而</b>有知，其几何离', '高中常考虚词｜《祭十二郎文》', NULL, 0, 0),
(1397, 2, '而', 'ér', '<连>表修饰', '吾尝跂<b>而</b>望矣，不如登高之博见也', '高中必修上册｜《劝学》', NULL, 0, 0),
(1398, 2, '而', 'ér', '<连>表修饰', '填然鼓之，兵刃既接，弃甲曳兵<b>而</b>走', '高中常考虚词｜《寡人之于国也》', NULL, 0, 0),
(1399, 2, '而', 'ér', '<连>表因果；因而', '余亦悔其随之<b>而</b>不得极夫游之乐也', '高中常考虚词｜《游褒禅山记》', NULL, 0, 0),
(1400, 2, '而', 'ér', '<连>表因果；因而', '表恶其能<b>而</b>不用也', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1401, 2, '而', 'ér', '<连>表目的；来；用来', '缦立远视，<b>而</b>望幸焉', '高中必修下册｜《阿房宫赋》', NULL, 0, 0),
(1402, 2, '而', 'ér', '<连>表目的；来；用来', '籍吏民，封府库，<b>而</b>待将军', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1403, 2, '而', 'ér', '<代>第二人称代词；你的；你', '<b>而</b>翁归，自与汝复算耳', '高中必修下册｜《促织》', NULL, 0, 0),
(1404, 2, '而', 'ér', '<代>第二人称代词；你的；你', '妪每谓余曰：“某所，<b>而</b>母立于兹', '高中选择性必修下册｜《项脊轩志》', NULL, 0, 0),
(1405, 2, '而', 'ér', '<动>像；好像；如同', '军惊<b>而</b>坏都舍', '高中常考虚词｜《察今》', NULL, 0, 0),
(1406, 2, '而', 'ér', '<助>表限止；罢了', '闻道有先后，术业有专攻，如是<b>而</b>已', '高中必修上册｜《师说》', NULL, 0, 0),
(1407, 2, '而', 'ér', '<助>表限止；罢了', '我决起<b>而</b>飞，枪榆枋<b>而</b>止，时则不至，<b>而</b>控于地<b>而</b>已矣', '高中常考虚词｜《逍遥游》', NULL, 0, 0),
(1408, 2, '而', 'ér', '<副>才；方才', '臣鞠躬尽瘁，死<b>而</b>后已。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1409, 2, '而', 'ér', '<副>才；方才', '三月<b>而</b>后成。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1410, 2, '而', 'ér', '<副>何况', '臣虽下愚，知其不可，<b>而</b>况于明哲乎', '高中必修下册｜《谏太宗十思疏》', NULL, 0, 0),
(1411, 2, '而', 'ér', '<副>不久；一会儿', '既<b>而</b>以吴民之乱请于朝，按诛五人', '高中常考虚词｜《五人墓碑记》', NULL, 0, 0),
(1412, 2, '而', 'ér', '<副>不久；一会儿', '既<b>而</b>得其尸于井，因<b>而</b>化怒为悲，抢呼欲绝', '高中必修下册｜《促织》', NULL, 0, 0),
(1413, 2, '何', 'hé', '<代>为什么；什么原因', '<b>何</b>者？严大国之威以修敬也。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1414, 2, '何', 'hé', '<代>为什么；什么原因', '齐人未尝赂秦，终继五国迁灭，<b>何</b>哉？', '高中必修下册｜《六国论》', NULL, 0, 0),
(1415, 2, '何', 'hé', '<代>哪里；什么', '大王来<b>何</b>操？', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1416, 2, '何', 'hé', '<代>哪里；什么', '一旦山陵崩，长安君<b>何</b>以自托于赵？', '高中常考虚词｜《触龙说赵太后》', NULL, 0, 0),
(1417, 2, '何', 'hé', '<代>什么；哪', '其间旦暮闻<b>何</b>物，杜鹃啼血猿哀鸣。', '高中常考虚词｜《琵琶行》', NULL, 0, 0),
(1418, 2, '何', 'hé', '<代>什么；哪', '然则<b>何</b>时而乐耶？', '高中常考虚词｜《岳阳楼记》', NULL, 0, 0),
(1419, 2, '何', 'hé', '<副>为什么；怎么', '<b>何</b>不按兵束甲，北面而事之？', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1420, 2, '何', 'hé', '<副>为什么；怎么', '徐公<b>何</b>能及君也？', '高中常考虚词｜《邹忌讽齐王纳谏》', NULL, 0, 0),
(1421, 2, '何', 'hé', '<副>怎么；多么；怎么这样', '至于誓天断发，泣下沾襟，<b>何</b>其衰也！', '高中常考虚词｜《伶官传序》', NULL, 0, 0),
(1422, 2, '何', 'hé', '<语气>啊', '新妇车在后，隐隐<b>何</b>甸甸。', '高中常考虚词｜《孔雀东南飞》', NULL, 0, 0),
(1423, 2, '何', 'hé', '<动>喝问', '信臣精卒陈利兵而谁<b>何</b>。', '高中选择性必修中册｜《过秦论》', NULL, 0, 0),
(1424, 2, '何', 'hé', '<副>怎么样；怎么办；为什么', '以五十步笑百步，则<b>何</b>如', '高中常考虚词｜《季氏将伐颛臾》', NULL, 0, 0),
(1425, 2, '何', 'hé', '<副>怎么样；怎么办；为什么', '沛公大惊，曰：“为之奈<b>何</b>？”', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1426, 2, '何', 'hé', '<介>拿什么；凭什么', '一旦山陵崩，长安君<b>何</b>以自托于赵', '高中常考虚词｜《触龙说赵太后》', NULL, 0, 0),
(1427, 2, '何', 'hé', '<介>拿什么；凭什么', '不为者与不能者之形<b>何</b>以异', '高中必修下册｜《齐桓晋文之事》', NULL, 0, 0),
(1428, 2, '何', 'hé', '<副>不久；没多久', '抚军不忘所自，无<b>何</b>，宰以卓异闻，宰悦，免成役', '高中必修下册｜《促织》', NULL, 0, 0),
(1429, 2, '何', 'hé', '<副>怎能', '阿母谓府吏：<b>何</b>乃太区区', '高中常考虚词｜《孔雀东南飞》', NULL, 0, 0),
(1430, 2, '乎', 'hū', '<语气>表疑问或反问；吗；呢', '几寒<b>乎</b>？欲食<b>乎</b>？', '高中选择性必修下册｜《项脊轩志》', NULL, 0, 0),
(1431, 2, '乎', 'hū', '<语气>表疑问或反问；吗；呢', '欲安所归<b>乎</b>？', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1432, 2, '乎', 'hū', '<语气>表疑问或反问；吗；呢', '布衣之交尚不相欺，况在国<b>乎</b>？', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1433, 2, '乎', 'hū', '<语气>表疑问或反问；吗；呢', '吾师道也，夫庸知其年之先后生于吾<b>乎</b>？', '高中必修上册｜《师说》', NULL, 0, 0),
(1434, 2, '乎', 'hū', '<语气>表测度或商量；吧', '日食饮得无衰<b>乎</b>', '高中常考虚词｜《触龙说赵太后》', NULL, 0, 0),
(1435, 2, '乎', 'hū', '<语气>表测度或商量；吧', '今亡亦死，举大计亦死，等死，死国可<b>乎</b>？', '高中常考虚词｜《陈涉世家》', NULL, 0, 0),
(1436, 2, '乎', 'hū', '<语气>表感叹或祈使；啊；呀', '宜<b>乎</b>百姓之谓我爱也', '高中必修下册｜《齐桓晋文之事》', NULL, 0, 0),
(1437, 2, '乎', 'hū', '<语气>表感叹或祈使；啊；呀', '西望夏口，东望武昌，山川相缪，郁<b>乎</b>苍苍', '高中必修上册｜《赤壁赋》', NULL, 0, 0),
(1438, 2, '乎', 'hū', '<语气>表停顿', '于是<b>乎</b>书。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1439, 2, '乎', 'hū', '<介>相当于“于”；在；从', '醉翁之意不在酒，在<b>乎</b>山水之间也。', '高中常考虚词｜《岳阳楼记》', NULL, 0, 0),
(1440, 2, '乎', 'hū', '<介>相当于“于”；比', '今虽死<b>乎</b>此，比吾乡邻之死则已后矣。', '高中常考虚词｜《捕蛇者说》', NULL, 0, 0),
(1441, 2, '乎', 'hū', '<介>相当于“于”；在；从', '生<b>乎</b>吾前，其闻道也固先<b>乎</b>吾？', '高中必修上册｜《师说》', NULL, 0, 0),
(1442, 2, '乎', 'hū', '<介>相当于“于”；对；对于', '君子博学而日参省<b>乎</b>己。', '高中选择性必修上册｜《论语》', NULL, 0, 0),
(1443, 2, '乎', 'hū', '<介>相当于“于”；在；从', '亦无怪<b>乎</b>其私之也。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1444, 2, '乎', 'hū', '<介>相当于“于”；比', '盖进<b>乎</b>技矣。', '高中必修下册｜《庖丁解牛》', NULL, 0, 0),
(1445, 2, '乎', 'hū', '<介>相当于“于”；比', '以吾一日长<b>乎</b>尔。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1446, 2, '乎', 'hū', '<助>词尾；……的样子；……地', '以无厚入有间，恢恢<b>乎</b>其于游刃必有余地矣', '高中必修下册｜《庖丁解牛》', NULL, 0, 0),
(1447, 2, '乎', 'hū', '<助>词尾；……的样子；……地', '浩浩<b>乎</b>如冯虚御风，而不知其所止；飘飘<b>乎</b>如遗世独立，羽化而登仙', '高中必修上册｜《赤壁赋》', NULL, 0, 0),
(1448, 2, '乃', 'nǎi', '<副>表承接；才；这才；就', '设九宾于廷，臣<b>乃</b>敢上璧。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1449, 2, '乃', 'nǎi', '<副>表承接；才；这才；就', '度我至军中，公<b>乃</b>入。', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1450, 2, '乃', 'nǎi', '<副>表转折；却；竟然；反而', '问今是何世，<b>乃</b>不知有汉。', '高中常考虚词｜《桃花源记》', NULL, 0, 0),
(1451, 2, '乃', 'nǎi', '<副>表转折；却；竟然；反而', '今其智<b>乃</b>反不能及。', '高中必修上册｜《师说》', NULL, 0, 0),
(1452, 2, '乃', 'nǎi', '<副>只；仅', '项王<b>乃</b>复引兵而东，至东城，<b>乃</b>有二十八骑。', '高中常考虚词｜《项羽本纪》', NULL, 0, 0),
(1453, 2, '乃', 'nǎi', '<动>是；就是', '若事之不济，此<b>乃</b>天也。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1454, 2, '乃', 'nǎi', '<动>是；就是', '嬴<b>乃</b>夷门抱关者也。', '高中常考虚词｜《信陵君窃符救赵》', NULL, 0, 0),
(1455, 2, '乃', 'nǎi', '<代>第二人称；你的；你', '王师北定中原日，家祭无忘告<b>乃</b>翁。', '高中常考虚词｜《示儿》', NULL, 0, 0),
(1456, 2, '乃', 'nǎi', '<代>这样', '夫我<b>乃</b>行之，反而求之，不得吾心', '高中必修下册｜《齐桓晋文之事》', NULL, 0, 0),
(1457, 2, '乃', 'nǎi', '<副>恐怕', '今君王既栖于会稽之上，然后<b>乃</b>求谋臣，无<b>乃</b>后乎', '高中常考虚词｜《勾践灭吴》', NULL, 0, 0),
(1458, 2, '乃', 'nǎi', '<副>恐怕', '无<b>乃</b>尔是过与', '高中常考虚词｜《季氏将伐颛臾》', NULL, 0, 0),
(1459, 2, '乃', 'nǎi', '<副>这样', '府吏再拜还，长叹空房中，作计<b>乃</b>尔立', '高中常考虚词｜《孔雀东南飞》', NULL, 0, 0),
(1460, 2, '其', 'qí', '<代>第三人称代词；他的；它的；他们的', '臣从<b>其</b>计，大王亦幸赦臣。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1461, 2, '其', 'qí', '<代>第三人称代词；他；它；他们', '秦王恐<b>其</b>破壁。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1462, 2, '其', 'qí', '<代>第三人称代词；他；它；他们', '<b>其</b>闻道也固先乎吾。', '高中必修上册｜《师说》', NULL, 0, 0),
(1463, 2, '其', 'qí', '<代>第一或第二人称；我的；我；你的；你', '而余亦悔<b>其</b>随之而不得极夫游之乐也。', '高中常考虚词｜《游褒禅山记》', NULL, 0, 0),
(1464, 2, '其', 'qí', '<代>第一或第二人称；我的；我；你的；你', '老臣以媪为长安君计短也，故以为<b>其</b>爱不若燕后', '高中常考虚词｜《触龙说赵太后》', NULL, 0, 0),
(1465, 2, '其', 'qí', '<代>指示代词；那；那个；那些；那里', '及<b>其</b>出，则或咎<b>其</b>欲出者。', '高中常考虚词｜《游褒禅山记》', NULL, 0, 0),
(1466, 2, '其', 'qí', '<代>指示代词；这；这个；这些', '有蒋氏者，专<b>其</b>利三世矣。', '高中常考虚词｜《捕蛇者说》', NULL, 0, 0),
(1467, 2, '其', 'qí', '<代>其中的', '于乱石间择<b>其</b>一二扣之。', '高中选择性必修下册｜《石钟山记》', '在乱石中选择其中的一两块敲击它。', 0, 0),
(1468, 2, '其', 'qí', '<副>表祈使；可；还是', '寡人欲以五百里之地易安陵，安陵君<b>其</b>许寡人！', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1469, 2, '其', 'qí', '<副>表祈使；可；还是', '攻之不克，围之不继，吾<b>其</b>还也。', '高中必修下册｜《烛之武退秦师》', NULL, 0, 0),
(1470, 2, '其', 'qí', '<副>表揣测；恐怕；或许；大概；可能', '圣人之所以为圣，愚人之所以为愚，<b>其</b>皆出于此乎？', '高中必修上册｜《师说》', NULL, 0, 0),
(1471, 2, '其', 'qí', '<副>表揣测；恐怕；或许；大概；可能', '王之好乐甚，则齐国<b>其</b>庶几乎？', '高中常考虚词｜《庄暴见孟子》', NULL, 0, 0),
(1472, 2, '其', 'qí', '<副>表反问；难道；怎么', '以残年余力，曾不能毁山之一毛，<b>其</b>如土石何？', '高中必修上册｜《愚公移山》', NULL, 0, 0),
(1473, 2, '其', 'qí', '<副>表反问；难道；怎么', '尽吾志也而不能至者，可以无悔矣，<b>其</b>孰能讥之乎？', '高中常考虚词｜《游褒禅山记》', NULL, 0, 0),
(1474, 2, '其', 'qí', '<连>表选择；是……还是……', '<b>其</b>真无马邪？<b>其</b>真不知马也？', '高中常考虚词｜《马说》', NULL, 0, 0),
(1475, 2, '其', 'qí', '<连>表假设；如果', '<b>其</b>业有不精，德有不成者，非天质之卑，则心不若余之专耳。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1476, 2, '其', 'qí', '<助>调节音节；不译', '路曼曼<b>其</b>修远兮，吾将上下而求索', '高中常考虚词｜《离骚》', NULL, 0, 0),
(1477, 2, '其', 'qí', '<副>多么', '至于誓天断发，泣下沾襟，何<b>其</b>衰也!', '高中常考虚词｜《伶官传序》', NULL, 0, 0),
(1478, 2, '且', 'qiě', '<连>表递进；而且；并且', '<b>且</b>立石于其墓之门', '高中常考虚词｜《五人墓碑记》', NULL, 0, 0),
(1479, 2, '且', 'qiě', '<连>表递进；而且；并且', '肃宣权旨，论天下事势，致殷勤之意，<b>且</b>问备曰。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1480, 2, '且', 'qiě', '<连>表递进；况且；再说', '<b>且</b>壮士不死即已，死即举大名耳。', '高中常考虚词｜《陈涉世家》', NULL, 0, 0),
(1481, 2, '且', 'qiě', '<连>表递进；况且；再说', '<b>且</b>燕赵处秦革灭殆尽之际。', '高中必修下册｜《六国论》', NULL, 0, 0),
(1482, 2, '且', 'qiě', '<连>表让步；尚且；还', '臣死<b>且</b>不避，卮酒安足辞！', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1483, 2, '且', 'qiě', '<连>表让步；尚且；还', '故之圣人，其出人也远矣，犹<b>且</b>从师而问焉', '高中必修上册｜《师说》', NULL, 0, 0),
(1484, 2, '且', 'qiě', '<连>表并列；又；又……又……', '示赵弱<b>且</b>怯也。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1485, 2, '且', 'qiě', '<连>表并列；又；又……又……', '命如南山石，四体康<b>且</b>直', '高中常考虚词｜《孔雀东南飞》', NULL, 0, 0),
(1486, 2, '且', 'qiě', '<副>将；将要', '有怠而欲出者，曰：“不出，火<b>且</b>尽”', '高中常考虚词｜《游褒禅山记》', NULL, 0, 0),
(1487, 2, '且', 'qiě', '<副>将；将要', '若属皆<b>且</b>为所虏', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1488, 2, '且', 'qiě', '<副>暂且；姑且', '存者<b>且</b>偷生，死者长已矣！', '高中常考虚词｜《石壕吏》', NULL, 0, 0),
(1489, 2, '且', 'qiě', '<副>暂且；姑且', '誓不相隔卿，<b>且</b>暂还家去。', '高中常考虚词｜《孔雀东南飞》', NULL, 0, 0),
(1490, 2, '且', 'qiě', '<连>表递进；况且；再说', '<b>且</b>夫天下非小弱也，雍州之地，肴函之固，自若也', '高中选择性必修中册｜《过秦论》', NULL, 0, 0),
(1491, 2, '且', 'qiě', '<连>表递进；况且；再说', '<b>且</b>夫天地之间，物各有主', '高中必修上册｜《赤壁赋》', NULL, 0, 0),
(1492, 2, '且', 'qiě', '<介>就像', '<b>且</b>如今年冬，未休关西卒', '高中常考虚词｜《兵车行》', NULL, 0, 0),
(1493, 2, '若', 'ruò', '<动>像；好像', '视之，形<b>若</b>土狗，梅花翅，方首，长胫，意似良', '高中必修下册｜《促织》', NULL, 0, 0),
(1494, 2, '若', 'ruò', '<动>像；好像', '吾不忍其觳觫，<b>若</b>无罪而就死地', '高中必修下册｜《齐桓晋文之事》', NULL, 0, 0),
(1495, 2, '若', 'ruò', '<代>你；你们；你的', '<b>若</b>入前为寿，寿毕，请以剑舞', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1496, 2, '若', 'ruò', '<代>你；你们；你的', '不者，<b>若</b>属皆且为所虏', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1497, 2, '若', 'ruò', '<代>这；这样；如此', '以<b>若</b>所为求<b>若</b>所欲，犹缘木而求鱼也', '高中必修下册｜《齐桓晋文之事》', NULL, 0, 0),
(1498, 2, '若', 'ruò', '<连>表假设；如果；假如', '<b>若</b>据而有之，此帝王之资也。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1499, 2, '若', 'ruò', '<连>表假设；如果；假如', '<b>若</b>备与彼协心，上下齐同，则宜抚安，与结盟好。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1500, 2, '若', 'ruò', '<连>表假设；如果；假如', '<b>若</b>不能，何不按兵束甲，北面而事之！', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1501, 2, '若', 'ruò', '<连>表选择；或；或者', '以万人<b>若</b>一郡降者，封万户。', '高中常考虚词｜《汉书·高帝纪》', NULL, 0, 0),
(1502, 2, '若', 'ruò', '<动>到；至于', '<b>若</b>民，则无恒产，因无恒心。', '高中必修下册｜《齐桓晋文之事》', NULL, 0, 0),
(1503, 2, '若', 'ruò', '<助>用于句首；要说那；像那', '<b>若</b>夫淫雨霏霏，连月不开。', '高中常考虚词｜《岳阳楼记》', NULL, 0, 0),
(1504, 2, '若', 'ruò', '<助>用于句首；要说那；像那', '<b>若</b>夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉', '高中常考虚词｜《逍遥游》', NULL, 0, 0),
(1505, 2, '若', 'ruò', '<副>心中有数；从容不迫', '指挥<b>若</b>定。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1506, 2, '若', 'ruò', '<副>怎么样', '以闲敝邑，<b>若</b>何？', '高中常考虚词｜《崤之战》', NULL, 0, 0),
(1507, 2, '若', 'ruò', '<数>几；多少', '车后<b>若</b>干递送夫。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1508, 2, '所', 'suǒ', '<名>处所；地方', '又间令吴广之次<b>所</b>旁丛祠中。', '高中常考虚词｜《陈涉世家》', NULL, 0, 0),
(1509, 2, '所', 'suǒ', '<名>处所；地方', '成反复自念，得无教我猎虫<b>所</b>耶？', '高中必修下册｜《促织》', NULL, 0, 0),
(1510, 2, '所', 'suǒ', '<助>所……的人；所……的事物；所……的情况', '道之<b>所</b>存，师之<b>所</b>存也。', '高中必修上册｜《师说》', NULL, 0, 0),
(1511, 2, '所', 'suǒ', '<助>所……的人；所……的事物；所……的情况', '过蒙拔擢，宠命优渥，岂敢盘桓，有<b>所</b>希冀', '高中选择性必修下册｜《陈情表》', NULL, 0, 0),
(1512, 2, '所', 'suǒ', '<助>所……的', '夜则以兵围<b>所</b>寓舍。', '高中常考虚词｜《指南录》后序', NULL, 0, 0),
