(1515, 2, '所', 'suǒ', '<助>与“为”组成被动结构', '仆以口语遇遭此祸，重为乡党<b>所</b>笑，以污辱先人', '高中常考虚词｜《报任安书》', NULL, 0, 0),
(1516, 2, '所', 'suǒ', '<助>用来……的方法；是用来……的', '吾<b>所</b>以待侯生者备矣，天下莫不闻', '高中常考虚词｜《信陵君窃符救赵》', NULL, 0, 0),
(1517, 2, '所', 'suǒ', '<助>用来……的方法；是用来……的', '师者，<b>所</b>以传道受业解惑也。', '高中必修上册｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 0, 0),
(1518, 2, '所', 'suǒ', '<助>……的原因；缘故', '臣<b>所</b>以去亲戚而事君者，徒慕君之高义也。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1519, 2, '所', 'suǒ', '<助>……的原因；缘故', '<b>所</b>以遣将守关者，备他盗之出入与非常也。', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1520, 2, '所', 'suǒ', '<助>所说的', '此<b>所</b>谓战胜于朝廷。', '高中常考虚词｜《邹忌讽齐王纳谏》', NULL, 0, 0),
