(1522, 2, '所', 'suǒ', '<副>到处', '石之铿然有声音者，<b>所</b>在皆是也。', '高中选择性必修下册｜《石钟山记》', NULL, 0, 0),
(1523, 2, '所', 'suǒ', '<名>所在之处；处所', '原来有这等一个<b>所</b>在，且回衙去', '高中常考虚词｜《闺塾》', NULL, 0, 0),
(1524, 2, '所', 'suǒ', '<名>所在之处；处所', '急趋之，折过墙隅，迷其<b>所</b>在。', '高中必修下册｜《促织》', NULL, 0, 0),
(1525, 2, '为', 'wéi', '<动>做；作为；充当；变成；成为', '斩木<b>为</b>兵，揭竿<b>为</b>旗。', '高中选择性必修中册｜《过秦论》', NULL, 0, 0),
