(1691, 2, '与', 'yǔ', '<介>哪如；与其……哪如……', '<b>与</b>其坐而待亡，孰若起而拯之', '高中常考虚词｜《冯婉贞》', NULL, 0, 0),
(1692, 2, '与', 'yǔ', '<介>哪如；与其……哪如……', '<b>与</b>其杀是童，孰若卖之', '高中常考虚词｜《童区寄传》', NULL, 0, 0),
(1693, 2, '则', 'zé', '<连>表承接；就；便', '项王曰：“壮士！赐之卮酒。”<b>则</b>与斗卮酒。', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1694, 2, '则', 'zé', '<连>表承接；就；便', '故木受绳<b>则</b>直，金就砺<b>则</b>利。', '高中必修上册｜《劝学》', NULL, 0, 0),
(1695, 2, '则', 'zé', '<连>表条件、假设；如果……就……；那么', '入<b>则</b>无法家拂士，出<b>则</b>无敌国外患者，国恒亡。', '高中常考虚词｜《生于忧患，死于安乐》', NULL, 0, 0),
(1696, 2, '则', 'zé', '<连>表条件、假设；如果……就……；那么', '向吾不为斯役，<b>则</b>久已病矣。', '高中常考虚词｜《捕蛇者说》', NULL, 0, 0),
(1697, 2, '则', 'zé', '<连>表并列；就；或不译', '位卑<b>则</b>足羞，官盛<b>则</b>近谀。', '高中必修上册｜《师说》', NULL, 0, 0),
(1698, 2, '则', 'zé', '<连>表并列；就；或不译', '入<b>则</b>孝，出<b>则</b>弟。', '高中常考虚词｜《论语·学而》', NULL, 0, 0),
(1699, 2, '则', 'zé', '<连>表转折、让步；可是；却；虽然', '于其身也，<b>则</b>耻师焉，惑矣。', '高中必修上册｜《师说》', '对于自己，却以从师学习为可耻，真是糊涂。', 0, 0),
(1700, 2, '则', 'zé', '<连>表转折、让步；可是；却；虽然', '手裁举，<b>则</b>双超忽而跃', '高中必修下册｜《促织》', NULL, 0, 0),
(1701, 2, '则', 'zé', '<连>表转折、让步；可是；却；虽然', '其室<b>则</b>迩，其人甚远。', '高中常考虚词｜《诗经》', NULL, 0, 0),
(1702, 2, '则', 'zé', '<连>表选择；就是；不是……就是……', '非死<b>则</b>徙尔', '高中常考虚词｜《捕蛇者说》', NULL, 0, 0),
(1703, 2, '则', 'zé', '<连>表选择；就是；不是……就是……', '非其身之所种<b>则</b>不食', '高中常考虚词｜《勾践灭吴》', NULL, 0, 0),
(1704, 2, '则', 'zé', '<副>表判断；是；就是', '此<b>则</b>岳阳楼之大观也。', '高中常考虚词｜《岳阳楼记》', '这就是岳阳楼的壮丽景象。', 0, 0),
(1705, 2, '则', 'zé', '<副>表已然；已经；原来', '及诸河，<b>则</b>在舟中矣。（', '高中常考虚词｜《肴之战》', NULL, 0, 0),
(1706, 2, '则', 'zé', '<名>篇；条', '十<b>则</b>。', '高中选择性必修上册｜《论语》', NULL, 0, 0),
(1707, 2, '则', 'zé', '<名>准则；法则', '以身作<b>则</b>。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1708, 2, '则', 'zé', '<动>效法', '遵后稷、公刘之业，<b>则</b>古公、公季之法。', '高中常考虚词｜《周本纪》', NULL, 0, 0),
(1709, 2, '则', 'zé', '<副>通“辄”；总是；常常', '居<b>则</b>曰：“不吾知也！”', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', NULL, 0, 0),
(1710, 2, '则', 'zé', '<副>只当是', '与窦娥烧一陌儿，<b>则</b>是看你死的孩儿面上。', '高中常考虚词｜《窦娥冤》', NULL, 0, 0),
(1711, 2, '则', 'zé', '<拟声>赞叹的声音', '连呼啧啧。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1712, 2, '者', 'zhě', '<助>指人、物、事、时、地等；……的', '有复言令长安君为质<b>者</b>，老妇必唾其面！', '高中常考虚词｜《触龙说赵太后》', NULL, 0, 0),
(1713, 2, '者', 'zhě', '<助>指人、物、事、时、地等；……的', '秦自缪公以来二十余君，未尝有坚明约束<b>者</b>也', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1714, 2, '者', 'zhě', '<助>用在数词后；……个方面；……样东西；……件事情', '此数<b>者</b>，用兵之患也。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1715, 2, '者', 'zhě', '<助>用在数词后；……个方面；……样东西；……件事情', '或异于二<b>者</b>之为，何哉？', '高中常考虚词｜《岳阳楼记》', NULL, 0, 0),
(1716, 2, '者', 'zhě', '<助>……的样子', '言之，貌若甚戚<b>者</b>', '高中常考虚词｜《捕蛇者说》', NULL, 0, 0),
(1717, 2, '者', 'zhě', '<助>……的样子', '然往来视之，觉无异能<b>者</b>', '高中常考虚词｜《黔之驴》', NULL, 0, 0),
(1718, 2, '者', 'zhě', '<助>定语后置的标志', '求人可使报秦<b>者</b>，未得。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1719, 2, '者', 'zhě', '<助>定语后置的标志', '顷之，烟炎张天，人马烧溺死<b>者</b>甚众', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1720, 2, '者', 'zhě', '<助>放在主语后；表判断', '廉颇<b>者</b>，赵之良将也。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1721, 2, '者', 'zhě', '<助>放在主语后；表判断', '师<b>者</b>，所以传道受业解惑也。', '高中必修上册｜《师说》', NULL, 0, 0),
(1722, 2, '者', 'zhě', '<助>用在时间词后；不译', '近<b>者</b>奉辞伐罪。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1723, 2, '者', 'zhě', '<助>用在时间词后；不译', '古<b>者</b>以天下为主，君为客。', '高中常考虚词｜《原君》', NULL, 0, 0),
(1724, 2, '者', 'zhě', '<助>放在分句末；引出原因', '然操遂能克绍，以弱为强<b>者</b>，非惟天时，抑亦人谋也。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
(1725, 2, '者', 'zhě', '<助>放在分句末；引出原因', '臣所以去亲戚而事君<b>者</b>，徒慕君之高义也。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1726, 2, '者', 'zhě', '<助>放在分句末；引出原因', '吾妻之美我<b>者</b>，私我也。', '高中常考虚词｜《邹忌讽齐王纳谏》', NULL, 0, 0),
(1727, 2, '者', 'zhě', '<语气>表疑问', '何<b>者</b>？严大国之威以修敬也', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1728, 2, '者', 'zhě', '<语气>表疑问', '谁为大王为此计<b>者</b>？', '高中必修下册｜《鸿门宴》', NULL, 0, 0),
(1729, 2, '之', 'zhī', '<代>第三人称代词；他；她；它（们）', '太后盛气而揖<b>之</b>。', '高中常考虚词｜《触龙说赵太后》', NULL, 0, 0),
(1730, 2, '之', 'zhī', '<代>第三人称代词；他；她；它（们）', '不知将军宽<b>之</b>至此也。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1731, 2, '之', 'zhī', '<代>第三人称代词；他；她；它（们）', '臣乃市井鼓刀屠者，而公子数存<b>之</b>。', '高中常考虚词｜《信陵君窃符救赵》', NULL, 0, 0),
(1732, 2, '之', 'zhī', '<代>第三人称代词；他；她；它（们）', '然语<b>之</b>，又恐汝日日为吾担忧。', '高中常考虚词｜《与妻书》', NULL, 0, 0),
