(1735, 2, '之', 'zhī', '<代>指示代词；这；此', '<b>之</b>二虫又何知。', '高中常考虚词｜《逍遥游》', NULL, 0, 0),
(1736, 2, '之', 'zhī', '<代>指示代词；这；此', '均<b>之</b>二策，宁许<b>之</b>以负秦曲。', '高中常考虚词｜《廉颇蔺相如列传》', NULL, 0, 0),
(1737, 2, '之', 'zhī', '<助>相当于现代汉语的“的”', '虎兕出于柙，龟玉毁于椟中，是谁<b>之</b>过与？', '高中常考虚词｜《季氏将伐颛臾》', NULL, 0, 0),
(1738, 2, '之', 'zhī', '<助>相当于现代汉语的“的”', '子而思报父母<b>之</b>仇，臣而思报君<b>之</b>仇。', '高中常考虚词｜《勾践灭吴》', NULL, 0, 0),
(1739, 2, '之', 'zhī', '<助>放在主语和谓语之间；取消句子独立性', '臣<b>之</b>壮也，犹不如人；今老矣，无能为也已。', '高中必修下册｜《烛之武退秦师》', NULL, 0, 0),
(1740, 2, '之', 'zhī', '<助>放在主语和谓语之间；取消句子独立性', '客<b>之</b>美我者，欲有求于我也。', '高中常考虚词｜《邹忌讽齐王纳谏》', NULL, 0, 0),
(1741, 2, '之', 'zhī', '<助>放在主语和谓语之间；取消句子独立性', '不患其众<b>之</b>不足也，而患其志行<b>之</b>少耻也。', '高中常考虚词｜《勾践灭吴》', NULL, 0, 0),
(1742, 2, '之', 'zhī', '<助>放在主语和谓语之间；取消句子独立性', '王无异于百姓<b>之</b>以王为爱也。', '高中常考虚词｜《常考虚词例句》', NULL, 0, 0),
(1743, 2, '之', 'zhī', '<助>宾语前置的标志', '句读<b>之</b>不知，惑<b>之</b>不解，或师焉，或不焉。', '高中必修上册｜《师说》', NULL, 0, 0),
(1744, 2, '之', 'zhī', '<助>宾语前置的标志', '譬若以肉投馁虎，何功<b>之</b>有哉？', '高中常考虚词｜《信陵君窃符救赵》', NULL, 0, 0),
(1745, 2, '之', 'zhī', '<助>宾语前置的标志', '诗云：“他人有心，予忖度<b>之</b>。”——夫子<b>之</b>谓也。', '高中必修下册｜《齐桓晋文之事》', NULL, 0, 0),
(1746, 2, '之', 'zhī', '<助>定语后置的标志', '蚓无爪牙<b>之</b>利，筋骨<b>之</b>强。', '高中必修上册｜《劝学》', NULL, 0, 0),
(1747, 2, '之', 'zhī', '<助>定语后置的标志', '人又谁能以身<b>之</b>察察，受物<b>之</b>汶汶者乎', '高中选择性必修中册｜《屈原列传》', NULL, 0, 0),
(1748, 2, '之', 'zhī', '<助>凑足音节；不译', '填然鼓<b>之</b>，兵刃既接，弃甲曳兵而走。', '高中常考虚词｜《寡人之于国也》', NULL, 0, 0),
(1749, 2, '之', 'zhī', '<助>凑足音节；不译', '余扃牖而居，久<b>之</b>，能以足音辨人。', '高中选择性必修下册｜《项脊轩志》', NULL, 0, 0),
(1750, 2, '之', 'zhī', '<助>凑足音节；不译', '顷<b>之</b>，烟炎张天。', '高中常考虚词｜《赤壁之战》', NULL, 0, 0),
