-- 按更新版《虚词字典.docx》同步21个虚词释义并补齐例句译文 v2
START TRANSACTION;
UPDATE `edu_chn_word_sense` SET `meaning` = CASE `id`
  WHEN 12 THEN '<连>表转折'
  WHEN 13 THEN '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等'
  WHEN 14 THEN '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等'
  WHEN 15 THEN '<助>用在因果复句或条件复句偏句的末尾，提示原因或条件'
  WHEN 16 THEN '<语助>用于句末；表示陈述或解释'
  WHEN 26 THEN '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”'
  WHEN 27 THEN '<代>第三人称代词。相当于“他（她）”、“它”、“他们”'
  WHEN 29 THEN '<介>介绍比较的对象，可译为“比”'
  WHEN 30 THEN '<介>相当于“于”；介绍比较对象。译为“与”、“对”、“比”'
  WHEN 31 THEN '<助>“所以”：表示行为所凭借的方式、方法或依据'
  WHEN 32 THEN '<连>表示转折，相当于“却”、“可是”'
  WHEN 41 THEN '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”'
  WHEN 42 THEN '<代>第三人称代词。相当于“他（她）的”、“它的”、“他们的”'
  WHEN 43 THEN '<连>表转折'
  WHEN 44 THEN '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等'
  WHEN 45 THEN '<介>相当于“于”；介绍处所、方向、时间。译为“在”、“由”等'
  WHEN 46 THEN '<助>用于句中，表示语气舒缓、停顿'
  WHEN 54 THEN '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”'
