  WHEN 1396 THEN '如果死后有知觉，那我们之间还要分别多久呢？'
  WHEN 1397 THEN '我曾经踮起脚跟远望，却不如登高看得广阔。'
  WHEN 1398 THEN '战鼓咚咚地敲响，兵器已经交锋，士兵们却丢下铠甲、拖着兵器逃跑。'
  WHEN 1399 THEN '我也后悔跟随他们出来，却没有能够尽情享受游览的乐趣。'
  WHEN 1400 THEN '曹操嫉妒他的才能却不能任用他。'
  WHEN 1401 THEN '长久地站着远远观望，盼望得到皇帝的宠幸。'
  WHEN 1402 THEN '登记官吏和百姓，封闭官府仓库，来等待将军。'
  WHEN 1403 THEN '你的父亲回来，自然会再来和你算账。'
  WHEN 1404 THEN '我祖母每次对我说：“某个地方，你的母亲曾经站在这里。”'
  WHEN 1405 THEN '军队受到惊吓，因而撞坏了城里的房屋。'
  WHEN 1406 THEN '听闻道理有先有后，学术技艺各有专门研究，如此而已。'
  WHEN 1407 THEN '我一下子起身飞向榆树和檀树，飞到树上就停下来；有时飞不上去，便落在地上罢了。'
  WHEN 1408 THEN '我恭敬谨慎地竭尽全力，直到死了才停止。'
  WHEN 1409 THEN '三个月以后才完成。'
  WHEN 1410 THEN '我虽然是最愚笨的人，也知道这样做不对，何况明智的人呢？'
  WHEN 1411 THEN '不久以后，因为吴地百姓作乱的事向朝廷请求，按照法律处死了五个人。'
  WHEN 1412 THEN '不久找到了他的尸体在井里，于是因而由愤怒变成悲伤，呼天抢地，哭喊得几乎气绝。'
  WHEN 1413 THEN '为什么呢？是为了显示大国的威严来表示敬意。'
  WHEN 1414 THEN '齐国不曾贿赂秦国，最终也随着五国灭亡，为什么呢？'
  WHEN 1415 THEN '大王来的时候带了什么东西？'
  WHEN 1416 THEN '一旦太后去世，长安君将凭什么在赵国托身呢？'
  WHEN 1417 THEN '早晚听到的是什么声音呢？是杜鹃啼血、猿猴哀鸣。'
  WHEN 1418 THEN '那么什么时候才快乐呢？'
  WHEN 1419 THEN '为什么不放下武器、捆束铠甲，面向北方侍奉他呢？'
  WHEN 1420 THEN '徐公怎么能比得上您呢？'
  WHEN 1421 THEN '等到对天发誓、割断头发，眼泪流下沾湿衣襟，怎么衰败到这种地步啊！'
  WHEN 1422 THEN '新娘的车在后面，车轮声隐隐约约，轰轰作响。'
  WHEN 1423 THEN '拿着精锐的臣子和士卒、锋利的兵器来喝问：“是谁？”'
  WHEN 1424 THEN '那么怎么样呢？'
  WHEN 1425 THEN '刘邦大吃一惊，说：“这件事怎么办呢？”'
  WHEN 1426 THEN '一旦太后去世，长安君将凭什么在赵国托身呢？'
  WHEN 1427 THEN '不去做和不能做的情形有什么不同呢？'
  WHEN 1428 THEN '巡抚没有忘记成名的来历，不久，县令便因他的才能出众而听闻于上级，县令很高兴，免除了成名的差役。'
  WHEN 1429 THEN '母亲对府吏说：“为什么竟然这样过分愚拙？”'
  WHEN 1430 THEN '天气有点冷吗？想吃东西吗？'
  WHEN 1431 THEN '想要到哪里去归附呢？'
  WHEN 1432 THEN '平民之间的交往尚且不互相欺骗，何况在国家之间呢？'
  WHEN 1433 THEN '我学习的是道理，哪里要了解他的年龄比我大还是小呢？'
  WHEN 1434 THEN '每天的饮食该不会减少了吧？'
  WHEN 1435 THEN '现在逃亡也是死，发动大事也是死，同样是死，为国事而死可以吗？'
  WHEN 1436 THEN '看来百姓认为我吝啬是适宜的了。'
  WHEN 1437 THEN '向西望是夏口，向东望是武昌，山水相互缭绕，草木郁郁苍苍。'
  WHEN 1438 THEN '于是就写下了这篇文章。'
  WHEN 1439 THEN '醉翁的情趣不在酒上，而在山水之间。'
  WHEN 1440 THEN '现在即使死在这里，也比我的乡邻死得晚了。'
  WHEN 1441 THEN '出生在我前面的人，他懂得道理本来就比我早；出生在我后面的人，他懂得道理也可能比我早。'
  WHEN 1442 THEN '君子广泛学习并且每天检查反省自己。'
  WHEN 1443 THEN '也就不奇怪他偏爱自己的孩子了。'
  WHEN 1444 THEN '已经进入了技艺的境界。'
  WHEN 1445 THEN '因为我比你年长一天。'
  WHEN 1446 THEN '用没有厚度的刀刃插入有间隙的骨节，刀刃游动起来宽绰有余。'
  WHEN 1447 THEN '浩浩荡荡仿佛凌空乘风而行，不知停在哪里；飘飘然像脱离尘世、独立存在，飞升成仙。'
  WHEN 1448 THEN '在朝廷上设置九宾的礼仪，我才敢把和氏璧献上去。'
  WHEN 1449 THEN '估计我已经回到军营，您才进去。'
  WHEN 1450 THEN '问现在是什么朝代，竟然不知道有汉朝，更不必说魏朝和晋朝了。'
  WHEN 1451 THEN '现在他们的智慧反而赶不上这些人。'
  WHEN 1452 THEN '项王于是又带领军队向东走，到达东城时，只剩下二十八名骑兵。'
  WHEN 1453 THEN '如果事情不能成功，这就是天意。'
  WHEN 1454 THEN '嬴原来是夷门的守门人。'
  WHEN 1455 THEN '等到王师向北平定中原的那一天，家祭时不要忘记告诉你们的父亲。'
  WHEN 1456 THEN '可是我这样做了以后，反过来再寻求这样做的原因，却不明白自己的心意。'
  WHEN 1457 THEN '现在大王已经退守会稽山上，这才来寻求谋臣，恐怕太晚了吧。'
  WHEN 1458 THEN '恐怕该责备的是您吧。'
  WHEN 1459 THEN '府吏拜了两拜回去，在空房中长叹，打定主意的计划才这样确定下来。'
  WHEN 1460 THEN '我听从了他的计策，大王也幸运地赦免了我。'
  WHEN 1461 THEN '秦王害怕他撞破和氏璧。'
  WHEN 1462 THEN '他懂得道理本来就比我早。'
  WHEN 1463 THEN '可是我也后悔跟随他出来，却没有能够尽情享受游览的乐趣。'
  WHEN 1464 THEN '我认为赵太后替长安君考虑得短浅，所以认为她疼爱燕后。'
  WHEN 1465 THEN '等到出来以后，就有人责怪那个想要出来的人。'
  WHEN 1466 THEN '蒋氏独自享有这种好处已经三代了。'
  WHEN 1468 THEN '安陵君可要答应我啊！'
  WHEN 1469 THEN '进攻不能取胜，包围又没有后援，我们还是回去吧。'
  WHEN 1470 THEN '圣人之所以成为圣人、愚人之所以成为愚人，大概都出于这个原因吧？'
  WHEN 1471 THEN '大王喜爱音乐很厉害，那么齐国大概就差不多治理好了吧？'
  WHEN 1472 THEN '凭我残余的年岁和力量，连山上的一根草木都不能毁掉，能把土石怎么样呢？'
  WHEN 1473 THEN '竭尽我的志向却不能到达，便可以没有悔恨了，难道还有谁能讥笑我吗？'
  WHEN 1474 THEN '难道真的没有千里马吗？恐怕是真的不认识千里马啊。'
  WHEN 1475 THEN '如果他的学业有不精通、品德有不成就的地方，不是天资低下，就是用心不如我专一。'
  WHEN 1476 THEN '道路漫长而遥远，我将上天下地寻求真理。'
  WHEN 1477 THEN '等到对天发誓、割断头发，眼泪流下沾湿衣襟，怎么衰败到这种地步啊！'
  WHEN 1478 THEN '并且在他的墓门前立了一块石碑。'
  WHEN 1479 THEN '鲁肃宣布孙权的意旨，谈论天下的形势，表达殷切的情意，并且问刘备。'
  WHEN 1480 THEN '况且壮士不死就罢了，死了就要成就大的名声。'
  WHEN 1481 THEN '况且燕、赵两国正处在秦国变法改革、几乎灭亡的时刻。'
  WHEN 1482 THEN '我连死都不躲避，一杯酒哪里值得推辞！'
  WHEN 1483 THEN '所以古代的圣人，他们远远超过一般人，尚且跟从老师请教。'
  WHEN 1484 THEN '表明赵国弱小而且胆怯。'
  WHEN 1485 THEN '寿命像南山的石头一样长，身体健康而且挺直。'
  WHEN 1486 THEN '有懈怠而想出来的人说：“不出去，火就要燃尽了。”'
  WHEN 1487 THEN '你们这些人将要被他俘虏。'
  WHEN 1488 THEN '活着的人姑且偷生，死去的人永远完结了。'
  WHEN 1489 THEN '发誓不再同你分离，你暂且回娘家去。'
  WHEN 1490 THEN '况且天下并没有缩小削弱，雍州的土地、崤山函谷关的险固，仍然和原来一样。'
  WHEN 1491 THEN '况且天地之间，万物各有自己的主人。'
  WHEN 1492 THEN '况且像今年冬天，关西的士卒还没有休息。'
  WHEN 1493 THEN '看它的形状像土狗，长着梅花斑的翅膀，方头、长腿，心里认为它似乎是上好的。'
  WHEN 1494 THEN '我不忍心看它恐惧战栗，像没有罪却走向死地一样。'
  WHEN 1495 THEN '你进去上前敬酒，敬完酒，请求用剑起舞。'
  WHEN 1496 THEN '否则你们这些人都将被他俘虏。'
  WHEN 1497 THEN '拿你所做的去求你想要的，就像爬到树上去捉鱼一样。'
  WHEN 1498 THEN '如果占据它并拥有它，这是成就帝王事业的凭借。'
  WHEN 1499 THEN '如果刘备和他们同心协力，上下团结一致，就应该安抚他们，和他们结盟交好。'
  WHEN 1500 THEN '如果不能这样，为什么不放下武器、捆束铠甲，面向北方侍奉他呢？'
  WHEN 1501 THEN '用一万人或者一个郡投降的，封给他万户的封地。'
  WHEN 1502 THEN '至于百姓，如果没有固定的产业，就没有长久不变的心。'
  WHEN 1503 THEN '像那连绵不断的阴雨，接连几个月不放晴。'
  WHEN 1504 THEN '至于顺应天地万物的本性、驾驭六气的变化而遨游无穷境界的人，他还需要凭借什么呢？'
  WHEN 1505 THEN '指挥若定，十分从容。'
  WHEN 1506 THEN '用来使我国疲敝，怎么样呢？'
  WHEN 1507 THEN '车后还有几个人递送役夫。'
  WHEN 1508 THEN '又暗中让吴广到驻地旁边的丛林祠堂里去。'
  WHEN 1509 THEN '成反复思考，莫非是教我寻找蟋蟀的地方吗？'
  WHEN 1510 THEN '道理存在的地方，就是老师存在的地方。'
  WHEN 1511 THEN '过分承蒙提拔，恩命优厚，哪里敢徘徊不前，还有什么希望呢？'
  WHEN 1512 THEN '夜里就用兵包围了所住的房屋。'
  WHEN 1513 THEN '我所经过的屠户朱亥。'
  WHEN 1514 THEN '我听说如姬的父亲被人杀害。'
  WHEN 1515 THEN '我因为言语获罪遭遇这场灾祸，又被乡里人耻笑，使先人受到侮辱。'
  WHEN 1516 THEN '我用来对待侯生的礼数很周到，天下没有人不知道。'
  WHEN 1518 THEN '我之所以离开亲属来侍奉您，只是仰慕您的高尚品德。'
  WHEN 1519 THEN '派遣将领把守函谷关的原因，是防备其他盗贼的进入和意外的变故。'
  WHEN 1520 THEN '这就是所说的在朝廷上战胜别国。'
  WHEN 1521 THEN '不是我所说的传授道理、解答疑惑的老师。'
  WHEN 1522 THEN '石头敲击时发出铿锵声音的地方，到处都是这样。'
  WHEN 1523 THEN '原来有这样一个地方，暂且回衙门去吧。'
  WHEN 1524 THEN '急忙追赶它，转过墙角，迷失了它所在的地方。'
  WHEN 1525 THEN '砍下树木做兵器，举起竹竿做旗帜。'
  WHEN 1526 THEN '然后把天下作为家，把崤山函谷关作为宫殿。'
  WHEN 1527 THEN '最终彼此交欢，结为可以生死与共的朋友。'
  WHEN 1528 THEN '冰是水凝结而成的，却比水更寒冷。'
  WHEN 1529 THEN '我私下听说秦王善于演奏秦地的乐曲。'
  WHEN 1530 THEN '今天我替公子做了这些事，也就足够了。'
  WHEN 1531 THEN '向南夺取百越的土地，把它设置为桂林郡和象郡。'
  WHEN 1532 THEN '用礼来治理国家，说话却不谦让，所以讥笑他。'
  WHEN 1533 THEN '这只是灭亡的秦朝的后续罢了，我私下认为大王不应该采取这种做法。'
  WHEN 1534 THEN '两个小孩笑着说：“谁说你知道得多呢？”'
  WHEN 1535 THEN '如今别人正是刀和砧板，我们正是鱼和肉。'
  WHEN 1536 THEN '不是因为织布缓慢，而是同一家的妇女难以织成。'
  WHEN 1537 THEN '我们这些人现在要被他俘虏了。'
  WHEN 1538 THEN '自己死在别人手里，被天下人嘲笑，是什么原因呢？'
  WHEN 1539 THEN '否则你们这些人都将被他俘虏。'
  WHEN 1540 THEN '疲弱的士兵被人马践踏，陷在泥里死去的人很多。'
  WHEN 1541 THEN '千万不要因为回去就白白送死，贵贱的分别为什么这样轻易呢？'
  WHEN 1542 THEN '是为了住宅的华美、妻妾的侍奉和我所认识的穷困人的感激吗？'
  WHEN 1543 THEN '请允许我用赵国十五座城给秦王祝寿。'
  WHEN 1544 THEN '请允许我给大王谈谈音乐。'
  WHEN 1545 THEN '这件事怎么办呢？'
  WHEN 1546 THEN '如姬替公子哭泣。'
  WHEN 1547 THEN '趁他到来的时候，请允许我捆绑一个人从大王面前走过。'
  WHEN 1548 THEN '如今别人正是刀和砧板，我们正是鱼和肉，还推辞什么呢？'
  WHEN 1549 THEN '这是国家的重臣，为什么还要讨伐它呢？'
  WHEN 1551 THEN '堆积土石成为高山，风雨就从那里兴起。'
  WHEN 1552 THEN '这五个人，是周蓼洲先生被捕时，受到正义激励而死在这里的人。'
  WHEN 1553 THEN '况且把土石放在哪里呢？'
  WHEN 1554 THEN '如果不是第二次到那里，怎么知道它竟然是这样呢？'
  WHEN 1555 THEN '哪里有仁德的人在位，却可以做欺骗百姓的事呢？'
  WHEN 1556 THEN '还跟从老师请教他。'
  WHEN 1557 THEN '离开现在的墓地把他们安葬在那里，距离现在只不过十一个月。'
  WHEN 1558 THEN '还没有懂得活着的道理，怎么能懂得死呢？'
  WHEN 1559 THEN '杀鸡哪里用得着宰牛的大刀呢？'
  WHEN 1561 THEN '那么牛和羊有什么区别呢？'
  WHEN 1562 THEN '有的从师学习，有的不从师学习，小的方面学习，大的方面却丢弃了。'
  WHEN 1564 THEN '楼阁盘旋曲折，屋檐像鱼鳞一样排列，密集得不知有几千万座。'
  WHEN 1565 THEN '在乱石中选择一两处敲击，发出硿硿的声音。'
  WHEN 1566 THEN '城北的徐公，是齐国最美丽的人。'
  WHEN 1567 THEN '张良说：“刘邦的参乘樊哙，是这样的人。”'
  WHEN 1568 THEN '就是不忍心看它恐惧战栗，像无罪却走向死地，所以用羊替换了它。'
  WHEN 1569 THEN '像雷霆突然震响一样，是宫车经过了。'
  WHEN 1570 THEN '灭掉六国的是六国自己，不是秦国；使秦国灭族的是秦国自己，不是天下人。'
  WHEN 1571 THEN '等到对天发誓、割断头发，眼泪流下沾湿衣襟，怎么衰败到这种地步啊！'
  WHEN 1572 THEN '公子难道是怕死吗？为什么哭泣呢？'
  WHEN 1573 THEN '假使秦国又爱护六国的百姓，那么传到三世乃至万世做君王，谁能够灭掉它呢？'
  WHEN 1574 THEN '进攻不能取胜，包围又没有后援，我们还是回去吧。'
  WHEN 1575 THEN '我们应当共同谋划这件事，不要让姐姐有走投无路的忧虑啊。'
  WHEN 1576 THEN '这是关于石钟山的说法，人们常常怀疑它。'
  WHEN 1577 THEN '他懂得道理也比我早。'
  WHEN 1578 THEN '《诗经》说：“别人有心思，我可以揣测他。”说的就是先生您这样的人。'
  WHEN 1579 THEN '难道不是长久的计策、让子孙相继为王吗？'
  WHEN 1580 THEN '难道只是伶人才这样吗？'
  WHEN 1581 THEN '希望用十五座城请求交换和氏璧。'
  WHEN 1582 THEN '士大夫最终也不肯用小船在夜里停泊在陡峭的山壁下面。'
  WHEN 1583 THEN '凭借勇气在诸侯中闻名。'
  WHEN 1584 THEN '时间久了，能够凭脚步声辨认人。'
  WHEN 1585 THEN '都爱好文辞，并且凭借辞赋受到称赞。'
  WHEN 1586 THEN '曹操应当把鲁肃送还给乡里。'
  WHEN 1587 THEN '在八月十三日被斩首于市集。'
  WHEN 1588 THEN '在崇祯十七年夏天，从京城步行到华山，做了道士。'
  WHEN 1589 THEN '赵王难道会因为一块璧的缘故欺骗秦国吗？'
  WHEN 1590 THEN '怀王因为不知道忠臣的职分，所以在内被郑袖迷惑，在外被张仪欺骗。'
  WHEN 1591 THEN '现在用事实来核对它。'
  WHEN 1592 THEN '我的船只依次都向前行进。'
  WHEN 1593 THEN '以一人抵挡十人。'
  WHEN 1594 THEN '夜以继日，日夜不停。'
  WHEN 1595 THEN '把秋天作为婚期。'
  WHEN 1596 THEN '平坦而且近，游览的人就多。'
  WHEN 1597 THEN '忽然间魂惊魄动。'
  WHEN 1598 THEN '我和四个人举着火把进去。'
  WHEN 1599 THEN '樊哙侧过他的盾牌来撞击。'
  WHEN 1600 THEN '请立太子为王，来断绝秦国的希望。'
  WHEN 1601 THEN '被秦国积久的威势所胁迫，天天削减、月月割让，以至于走向灭亡。'
  WHEN 1602 THEN '不贿赂秦国的国家因为贿赂秦国的国家而灭亡。'
  WHEN 1603 THEN '诸侯因为公子贤能、门客众多，十多年不敢出兵谋取魏国。'
  WHEN 1604 THEN '接受遗命以来，早晚忧虑叹息。'
  WHEN 1605 THEN '从这里往前，十五座城都给赵国。'
  WHEN 1606 THEN '从王侯以下，没有不奢侈的。'
  WHEN 1607 THEN '反而因此使我的心情受到煎熬。'
  WHEN 1608 THEN '我认为赵太后替长安君考虑得短浅。'
  WHEN 1609 THEN '都认为比徐公美。'
  WHEN 1610 THEN '忠臣不一定被任用，贤者不一定被使用。'
  WHEN 1611 THEN '古人拿着蜡烛游玩，确实有原因啊。'
  WHEN 1612 THEN '本来已经因此对它感到奇怪了。'
  WHEN 1613 THEN '太阳一天天地西下，很快就要完全落尽了。'
  WHEN 1614 THEN '没有办法，就实行王道吗？'
  WHEN 1615 THEN '老虎像看待一般东西一样看它，觉得它是一个庞然大物，把它当作神来敬畏。'
  WHEN 1616 THEN '医生喜欢给没有病的人治病，把这当作自己的功劳！'
  WHEN 1617 THEN '向南夺取百越的土地，把它设置为桂林郡和象郡。'
  WHEN 1618 THEN '铸造它来制作十二个金人。'
  WHEN 1619 THEN '我因此记下这件事，是感叹郦道元的简略，也嘲笑李渤的浅陋。'
  WHEN 1620 THEN '公子先走而我没有送行，因此知道公子怨恨我又返回来了。'
  WHEN 1621 THEN '项王没有办法回答，说：“坐下。”'
  WHEN 1622 THEN '齐王把喜爱音乐的事情告诉我，我没有什么可以回答的。'
  WHEN 1623 THEN '所以不积累半步，就没有办法到达千里；不汇聚细小水流，就没有办法形成江海。'
  WHEN 1624 THEN '我没有祖母，就没有办法活到今天；祖母没有我，就没有办法终了她的余年。'
  WHEN 1625 THEN '没有不依据地势的形状来刻画的，各自具有各自的情态。'
  WHEN 1626 THEN '善于作战的人顺应敌我形势，因势利导。'
  WHEN 1628 THEN '依靠别人的力量却反过来损害他，这是不仁义的。'
  WHEN 1629 THEN '又因为用丰厚的礼物收买当权者靳尚。'
  WHEN 1630 THEN '不如趁此机会优厚地款待他。'
  WHEN 1631 THEN '趁机在座位上袭击刘邦。'
  WHEN 1632 THEN '通过门客引领到蔺相如门前谢罪。'
  WHEN 1633 THEN '因为修建玉清宫，砍伐山上的树木取材，才有人看见它。'
  WHEN 1634 THEN '对于恩惠所施加的人，就要想到不要因一时高兴而错误地奖赏。'
  WHEN 1635 THEN '于是拔出刀砍向前面的奏案。'
  WHEN 1636 THEN '相如于是拿着璧退后站立。'
  WHEN 1637 THEN '到现在还没有相会的机会。'
  WHEN 1638 THEN '所以事情因循世俗，却要使准备适合事情的需要。'
  WHEN 1639 THEN '承接已有的基业，沿袭前代的策略。'
  WHEN 1640 THEN '加上有军队来攻打，接着又有饥荒。'
  WHEN 1641 THEN '于是就在朝廷上设置九宾的礼仪。'
  WHEN 1642 THEN '缙绅、大夫和士人聚集在左丞相府，没有人知道计策从哪里来。'
  WHEN 1643 THEN '从小路逃走，把和氏璧送回赵国。'
  WHEN 1644 THEN '楚国有多余的土地，却不够分给百姓。'
  WHEN 1645 THEN '在别人看来是值得讥笑的，在自己却是悔恨。'
  WHEN 1646 THEN '学业由于勤奋而精通，由于嬉游而荒废。'
  WHEN 1647 THEN '请奉命向孙将军请求救援。'
  WHEN 1648 THEN '鲁肃听说刘表去世了，把这件事告诉孙权说……'
  WHEN 1649 THEN '爱自己的孩子，选择老师来教他；对于他自己，却以从师学习为可耻。'
  WHEN 1650 THEN '您被赵王宠幸。'
  WHEN 1651 THEN '所以在内被郑袖迷惑，在外被张仪欺骗。'
  WHEN 1652 THEN '身高八尺，常常把自己比作管仲、乐毅。'
  WHEN 1653 THEN '燕王想同您结交。'
  WHEN 1654 THEN '孔子说：“苛刻的政治比老虎还要凶猛。”'
  WHEN 1656 THEN '在这时宾客没有不变了脸色离开席位的。'
  WHEN 1657 THEN '我的祖父死在这里，我的父亲也死在这里。'
  WHEN 1658 THEN '于是秦王很不高兴，为此击打一块瓦缶。'
  WHEN 1659 THEN '于是我对此有所感叹。'
  WHEN 1660 THEN '于是用黑色衣服安葬文公，晋国从这时开始穿黑色丧服。'
  WHEN 1661 THEN '于是秦王很不高兴，为此击打一只瓦缶。'
  WHEN 1662 THEN '吴地百姓正感到痛心，于是趁他声色严厉地呵斥时，喧闹着追逐起来。'
  WHEN 1663 THEN '于是替长安君约定车辆一百辆，把他送到齐国做人质。'
  WHEN 1664 THEN '我将长久地被大方之家嘲笑。'
  WHEN 1665 THEN '现在这条溪水偏偏被愚弄而受到侮辱，为什么呢？'
  WHEN 1666 THEN '刘邦的军队驻扎在霸上，还没有能够和项羽相见。'
  WHEN 1667 THEN '你的父亲回来，自然会再来和你算账。'
  WHEN 1668 THEN '陈涉年轻时，曾经和别人一起被雇佣耕田。'
  WHEN 1669 THEN '给你三支箭，你一定不要忘记你父亲的遗志！'
  WHEN 1670 THEN '我和徐公相比，谁更美？'
  WHEN 1671 THEN '把秦国受贿赂所得的土地，同战胜别国所得的土地比较，实际上多一百倍。'
  WHEN 1672 THEN '然而谋臣和勇士，不能不培养并选择。'
  WHEN 1673 THEN '勾践把稻米和油脂装在船上出发。'
  WHEN 1674 THEN '生了三个孩子，公就给他们母亲衣食；生了两个孩子，公就给他们粮食。'
  WHEN 1675 THEN '就给他一只完整的猪腿。'
  WHEN 1676 THEN '给你三支箭，你一定不要忘记你父亲的遗志。'
  WHEN 1677 THEN '依靠别人的力量却反过来损害他，这是不仁义的；失去自己的同盟，不明智。'
  WHEN 1678 THEN '联合各国缔结盟约，彼此结为一体。'
  WHEN 1679 THEN '齐国亲附秦国，却不帮助其他五国。'
  WHEN 1680 THEN '庞暖是很容易对付的。'
  WHEN 1681 THEN '蹇叔的儿子参加了军队。'
  WHEN 1682 THEN '我赞同曾点。'
  WHEN 1683 THEN '早晨犯错晚上就改正，君子赞许他。'
  WHEN 1684 THEN '恐怕该责备的是您吧。'
  WHEN 1685 THEN '虎兕从笼子里跑出，龟甲和玉器在匣子里毁坏，这是谁的过错呢？'
  WHEN 1686 THEN '那么废除衅钟的仪式吗？'
  WHEN 1687 THEN '他对妻子说：“我和城北徐公相比，谁更美？”'
  WHEN 1688 THEN '刘邦说：“你和项伯相比，谁年长谁年幼？”'
  WHEN 1689 THEN '您看廉颇将军和秦王相比，谁更强？'
  WHEN 1690 THEN '我和徐公相比，谁更美？'
  WHEN 1691 THEN '与其坐着等待灭亡，不如站起来拯救它。'
  WHEN 1692 THEN '与其杀死这个孩子，不如把他卖掉。'
  WHEN 1693 THEN '项王说：“壮士！赏给他一杯酒。”于是给他一大杯酒。'
  WHEN 1694 THEN '所以木材用墨线量过就直，刀剑靠近磨刀石就锋利。'
  WHEN 1695 THEN '进入国内如果没有守法的大臣，离开国内如果没有敌国外患，国家常常会灭亡。'
  WHEN 1696 THEN '假如当初我不做这件差事，那么早已经困苦不堪了。'
  WHEN 1697 THEN '职位低就觉得羞耻，官职高就近于谄媚。'
