  WHEN 1557 THEN '离开现在的墓地把他们安葬在那里，距离现在只不过十一个月。'
  WHEN 1558 THEN '还没有懂得活着的道理，怎么能懂得死呢？'
  WHEN 1559 THEN '杀鸡哪里用得着宰牛的大刀呢？'
  WHEN 1561 THEN '那么牛和羊有什么区别呢？'
  WHEN 1562 THEN '有的从师学习，有的不从师学习，小的方面学习，大的方面却丢弃了。'
  WHEN 1564 THEN '楼阁盘旋曲折，屋檐像鱼鳞一样排列，密集得不知有几千万座。'
  WHEN 1565 THEN '在乱石中选择一两处敲击，发出硿硿的声音。'
  WHEN 1566 THEN '城北的徐公，是齐国最美丽的人。'
  WHEN 1567 THEN '张良说：“刘邦的参乘樊哙，是这样的人。”'
  WHEN 1568 THEN '就是不忍心看它恐惧战栗，像无罪却走向死地，所以用羊替换了它。'
  WHEN 1569 THEN '像雷霆突然震响一样，是宫车经过了。'
  WHEN 1570 THEN '灭掉六国的是六国自己，不是秦国；使秦国灭族的是秦国自己，不是天下人。'
  WHEN 1571 THEN '等到对天发誓、割断头发，眼泪流下沾湿衣襟，怎么衰败到这种地步啊！'
  WHEN 1572 THEN '公子难道是怕死吗？为什么哭泣呢？'
  WHEN 1573 THEN '假使秦国又爱护六国的百姓，那么传到三世乃至万世做君王，谁能够灭掉它呢？'
  WHEN 1574 THEN '进攻不能取胜，包围又没有后援，我们还是回去吧。'
  WHEN 1575 THEN '我们应当共同谋划这件事，不要让姐姐有走投无路的忧虑啊。'
  WHEN 1576 THEN '这是关于石钟山的说法，人们常常怀疑它。'
  WHEN 1577 THEN '他懂得道理也比我早。'
  WHEN 1578 THEN '《诗经》说：“别人有心思，我可以揣测他。”说的就是先生您这样的人。'
  WHEN 1579 THEN '难道不是长久的计策、让子孙相继为王吗？'
  WHEN 1580 THEN '难道只是伶人才这样吗？'
  WHEN 1581 THEN '希望用十五座城请求交换和氏璧。'
  WHEN 1582 THEN '士大夫最终也不肯用小船在夜里停泊在陡峭的山壁下面。'
  WHEN 1583 THEN '凭借勇气在诸侯中闻名。'
  WHEN 1584 THEN '时间久了，能够凭脚步声辨认人。'
  WHEN 1585 THEN '都爱好文辞，并且凭借辞赋受到称赞。'
  WHEN 1586 THEN '曹操应当把鲁肃送还给乡里。'
  WHEN 1587 THEN '在八月十三日被斩首于市集。'
  WHEN 1588 THEN '在崇祯十七年夏天，从京城步行到华山，做了道士。'
  WHEN 1589 THEN '赵王难道会因为一块璧的缘故欺骗秦国吗？'
  WHEN 1590 THEN '怀王因为不知道忠臣的职分，所以在内被郑袖迷惑，在外被张仪欺骗。'
  WHEN 1591 THEN '现在用事实来核对它。'
  WHEN 1592 THEN '我的船只依次都向前行进。'
  WHEN 1593 THEN '以一人抵挡十人。'
  WHEN 1594 THEN '夜以继日，日夜不停。'
  WHEN 1595 THEN '把秋天作为婚期。'
  WHEN 1596 THEN '平坦而且近，游览的人就多。'
  WHEN 1597 THEN '忽然间魂惊魄动。'
  WHEN 1598 THEN '我和四个人举着火把进去。'
  WHEN 1599 THEN '樊哙侧过他的盾牌来撞击。'
  WHEN 1600 THEN '请立太子为王，来断绝秦国的希望。'
  WHEN 1601 THEN '被秦国积久的威势所胁迫，天天削减、月月割让，以至于走向灭亡。'
  WHEN 1602 THEN '不贿赂秦国的国家因为贿赂秦国的国家而灭亡。'
  WHEN 1603 THEN '诸侯因为公子贤能、门客众多，十多年不敢出兵谋取魏国。'
  WHEN 1604 THEN '接受遗命以来，早晚忧虑叹息。'
  WHEN 1605 THEN '从这里往前，十五座城都给赵国。'
  WHEN 1606 THEN '从王侯以下，没有不奢侈的。'
  WHEN 1607 THEN '反而因此使我的心情受到煎熬。'
  WHEN 1608 THEN '我认为赵太后替长安君考虑得短浅。'
  WHEN 1609 THEN '都认为比徐公美。'
  WHEN 1610 THEN '忠臣不一定被任用，贤者不一定被使用。'
  WHEN 1611 THEN '古人拿着蜡烛游玩，确实有原因啊。'
  WHEN 1612 THEN '本来已经因此对它感到奇怪了。'
  WHEN 1613 THEN '太阳一天天地西下，很快就要完全落尽了。'
  WHEN 1614 THEN '没有办法，就实行王道吗？'
  WHEN 1615 THEN '老虎像看待一般东西一样看它，觉得它是一个庞然大物，把它当作神来敬畏。'
  WHEN 1616 THEN '医生喜欢给没有病的人治病，把这当作自己的功劳！'
  WHEN 1617 THEN '向南夺取百越的土地，把它设置为桂林郡和象郡。'
  WHEN 1618 THEN '铸造它来制作十二个金人。'
  WHEN 1619 THEN '我因此记下这件事，是感叹郦道元的简略，也嘲笑李渤的浅陋。'
  WHEN 1620 THEN '公子先走而我没有送行，因此知道公子怨恨我又返回来了。'
  WHEN 1621 THEN '项王没有办法回答，说：“坐下。”'
  WHEN 1622 THEN '齐王把喜爱音乐的事情告诉我，我没有什么可以回答的。'
  WHEN 1623 THEN '所以不积累半步，就没有办法到达千里；不汇聚细小水流，就没有办法形成江海。'
  WHEN 1624 THEN '我没有祖母，就没有办法活到今天；祖母没有我，就没有办法终了她的余年。'
  WHEN 1625 THEN '没有不依据地势的形状来刻画的，各自具有各自的情态。'
  WHEN 1626 THEN '善于作战的人顺应敌我形势，因势利导。'
  WHEN 1628 THEN '依靠别人的力量却反过来损害他，这是不仁义的。'
  WHEN 1629 THEN '又因为用丰厚的礼物收买当权者靳尚。'
  WHEN 1630 THEN '不如趁此机会优厚地款待他。'
  WHEN 1631 THEN '趁机在座位上袭击刘邦。'
  WHEN 1632 THEN '通过门客引领到蔺相如门前谢罪。'
  WHEN 1633 THEN '因为修建玉清宫，砍伐山上的树木取材，才有人看见它。'
  WHEN 1634 THEN '对于恩惠所施加的人，就要想到不要因一时高兴而错误地奖赏。'
  WHEN 1635 THEN '于是拔出刀砍向前面的奏案。'
  WHEN 1636 THEN '相如于是拿着璧退后站立。'
  WHEN 1637 THEN '到现在还没有相会的机会。'
  WHEN 1638 THEN '所以事情因循世俗，却要使准备适合事情的需要。'
  WHEN 1639 THEN '承接已有的基业，沿袭前代的策略。'
  WHEN 1640 THEN '加上有军队来攻打，接着又有饥荒。'
  WHEN 1641 THEN '于是就在朝廷上设置九宾的礼仪。'
  WHEN 1642 THEN '缙绅、大夫和士人聚集在左丞相府，没有人知道计策从哪里来。'
  WHEN 1643 THEN '从小路逃走，把和氏璧送回赵国。'
  WHEN 1644 THEN '楚国有多余的土地，却不够分给百姓。'
  WHEN 1645 THEN '在别人看来是值得讥笑的，在自己却是悔恨。'
  WHEN 1646 THEN '学业由于勤奋而精通，由于嬉游而荒废。'
  WHEN 1647 THEN '请奉命向孙将军请求救援。'
  WHEN 1648 THEN '鲁肃听说刘表去世了，把这件事告诉孙权说……'
  WHEN 1649 THEN '爱自己的孩子，选择老师来教他；对于他自己，却以从师学习为可耻。'
  WHEN 1650 THEN '您被赵王宠幸。'
  WHEN 1651 THEN '所以在内被郑袖迷惑，在外被张仪欺骗。'
  WHEN 1652 THEN '身高八尺，常常把自己比作管仲、乐毅。'
  WHEN 1653 THEN '燕王想同您结交。'
  WHEN 1654 THEN '孔子说：“苛刻的政治比老虎还要凶猛。”'
  WHEN 1656 THEN '在这时宾客没有不变了脸色离开席位的。'
  WHEN 1657 THEN '我的祖父死在这里，我的父亲也死在这里。'
  WHEN 1658 THEN '于是秦王很不高兴，为此击打一块瓦缶。'
  WHEN 1659 THEN '于是我对此有所感叹。'
  WHEN 1660 THEN '于是用黑色衣服安葬文公，晋国从这时开始穿黑色丧服。'
  WHEN 1661 THEN '于是秦王很不高兴，为此击打一只瓦缶。'
  WHEN 1662 THEN '吴地百姓正感到痛心，于是趁他声色严厉地呵斥时，喧闹着追逐起来。'
  WHEN 1663 THEN '于是替长安君约定车辆一百辆，把他送到齐国做人质。'
  WHEN 1664 THEN '我将长久地被大方之家嘲笑。'
  WHEN 1665 THEN '现在这条溪水偏偏被愚弄而受到侮辱，为什么呢？'
  WHEN 1666 THEN '刘邦的军队驻扎在霸上，还没有能够和项羽相见。'
  WHEN 1667 THEN '你的父亲回来，自然会再来和你算账。'
  WHEN 1668 THEN '陈涉年轻时，曾经和别人一起被雇佣耕田。'
  WHEN 1669 THEN '给你三支箭，你一定不要忘记你父亲的遗志！'
  WHEN 1670 THEN '我和徐公相比，谁更美？'
  WHEN 1671 THEN '把秦国受贿赂所得的土地，同战胜别国所得的土地比较，实际上多一百倍。'
  WHEN 1672 THEN '然而谋臣和勇士，不能不培养并选择。'
  WHEN 1673 THEN '勾践把稻米和油脂装在船上出发。'
  WHEN 1674 THEN '生了三个孩子，公就给他们母亲衣食；生了两个孩子，公就给他们粮食。'
  WHEN 1675 THEN '就给他一只完整的猪腿。'
  WHEN 1676 THEN '给你三支箭，你一定不要忘记你父亲的遗志。'
  WHEN 1677 THEN '依靠别人的力量却反过来损害他，这是不仁义的；失去自己的同盟，不明智。'
  WHEN 1678 THEN '联合各国缔结盟约，彼此结为一体。'
  WHEN 1679 THEN '齐国亲附秦国，却不帮助其他五国。'
  WHEN 1680 THEN '庞暖是很容易对付的。'
  WHEN 1681 THEN '蹇叔的儿子参加了军队。'
  WHEN 1682 THEN '我赞同曾点。'
  WHEN 1683 THEN '早晨犯错晚上就改正，君子赞许他。'
  WHEN 1684 THEN '恐怕该责备的是您吧。'
  WHEN 1685 THEN '虎兕从笼子里跑出，龟甲和玉器在匣子里毁坏，这是谁的过错呢？'
  WHEN 1686 THEN '那么废除衅钟的仪式吗？'
  WHEN 1687 THEN '他对妻子说：“我和城北徐公相比，谁更美？”'
  WHEN 1688 THEN '刘邦说：“你和项伯相比，谁年长谁年幼？”'
  WHEN 1689 THEN '您看廉颇将军和秦王相比，谁更强？'
  WHEN 1690 THEN '我和徐公相比，谁更美？'
  WHEN 1691 THEN '与其坐着等待灭亡，不如站起来拯救它。'
  WHEN 1692 THEN '与其杀死这个孩子，不如把他卖掉。'
  WHEN 1693 THEN '项王说：“壮士！赏给他一杯酒。”于是给他一大杯酒。'
  WHEN 1694 THEN '所以木材用墨线量过就直，刀剑靠近磨刀石就锋利。'
  WHEN 1695 THEN '进入国内如果没有守法的大臣，离开国内如果没有敌国外患，国家常常会灭亡。'
  WHEN 1696 THEN '假如当初我不做这件差事，那么早已经困苦不堪了。'
  WHEN 1697 THEN '职位低就觉得羞耻，官职高就近于谄媚。'
  WHEN 1698 THEN '在家就孝顺父母，出门就敬爱兄长。'
  WHEN 1700 THEN '手刚抬起，两只蟋蟀就迅速跳开了。'
  WHEN 1701 THEN '他的房屋相距很近，那个人却相隔很远。'
  WHEN 1702 THEN '不是死了，就是迁徙。'
  WHEN 1703 THEN '不是自己种的粮食就不吃。'
  WHEN 1705 THEN '等到了黄河边，却发现他已经在船里了。'
  WHEN 1706 THEN '十条。'
  WHEN 1707 THEN '以自身的行为作为榜样。'
  WHEN 1708 THEN '遵循后稷、公刘的事业，就是古公、公季的法度。'
  WHEN 1709 THEN '平日在家就说：“没有人了解我！”'
  WHEN 1710 THEN '给窦娥烧一陌纸钱，就算是看在你死去的孩子的面上。'
  WHEN 1711 THEN '接连发出啧啧的赞叹声。'
  WHEN 1712 THEN '如果再有人说让长安君去做人质，我一定吐他一脸唾沫。'
  WHEN 1713 THEN '秦穆公以来二十多位君主，从来没有能够坚定明确地遵守约定的。'
  WHEN 1714 THEN '这几件事，是用兵的祸患。'
  WHEN 1715 THEN '有人不同于这两种人的心情，为什么呢？'
  WHEN 1716 THEN '说起这些，脸色好像非常忧伤。'
  WHEN 1717 THEN '然而来来回回地观察它，觉得它没有什么特殊本领。'
  WHEN 1718 THEN '寻找一个可以出使回复秦国的人，没有找到。'
  WHEN 1719 THEN '不久，烟火冲天，人和马烧死、淹死的很多。'
  WHEN 1720 THEN '廉颇，是赵国的优秀将领。'
  WHEN 1721 THEN '老师，是用来传授道理、教授学业、解答疑难问题的人。'
  WHEN 1722 THEN '近来奉命讨伐有罪的人。'
  WHEN 1723 THEN '古时候把天下人作为主人，君主作为客人。'
  WHEN 1724 THEN '然而曹操最终能够战胜袁绍，以弱小变为强大，不只是天时，也是人的谋划。'
  WHEN 1725 THEN '我之所以离开亲属来侍奉您，只是仰慕您的高尚品德。'
  WHEN 1726 THEN '我的妻子认为我美，是因为偏爱我。'
  WHEN 1727 THEN '为什么呢？是为了显示大国的威严来表示敬意。'
  WHEN 1728 THEN '是谁替大王出了这个计策？'
  WHEN 1729 THEN '太后怒气冲冲地向他作揖。'
  WHEN 1730 THEN '不知道将军宽待我到了这样的地步。'
  WHEN 1731 THEN '我本是市井中击鼓宰牛的屠夫，可是公子多次救济我。'
  WHEN 1732 THEN '这样告诉你，又怕你每天替我担忧。'
  WHEN 1733 THEN '孔子想要这样做，我们两个大臣都不想这样做。'
  WHEN 1734 THEN '君子痛恨那些不说自己想要它，却一定要替自己的欲望找借口的人。'
  WHEN 1735 THEN '这两只小虫又知道什么呢？'
  WHEN 1736 THEN '比较这两种计策，宁可答应秦国使它承担理亏。'
  WHEN 1737 THEN '虎兕从笼子里跑出，龟甲和玉器在匣子里毁坏，这是谁的过错呢？'
  WHEN 1738 THEN '儿子想到要报父母的仇，臣子想到要报君主的仇。'
  WHEN 1739 THEN '我年轻时尚且不如别人，现在年老了，更没有能力了。'
  WHEN 1740 THEN '客人认为我美，是因为想要向我有所求。'
  WHEN 1741 THEN '不担心他们人数不足，却担心他们的志向品行缺少羞耻之心。'
  WHEN 1742 THEN '大王不要对百姓认为我吝啬这件事感到奇怪。'
  WHEN 1743 THEN '不懂得断句，不能解决疑惑，有的从师学习，有的不从师学习。'
  WHEN 1744 THEN '比如把肉投给饥饿的老虎，有什么功效呢？'
  WHEN 1745 THEN '《诗经》说：“别人有心思，我可以揣测他。”说的就是先生您这样的人。'
  WHEN 1746 THEN '蚯蚓没有锋利的爪牙和强健的筋骨。'
  WHEN 1747 THEN '世上又有谁能让洁白的身体蒙受污浊，受到外物玷污呢？'
  WHEN 1748 THEN '战鼓咚咚地敲响，兵器已经交锋，士兵们丢下铠甲、拖着兵器逃跑。'
  WHEN 1749 THEN '我关着窗子独自居住，时间久了，能够凭脚步声辨认人。'
  WHEN 1750 THEN '一会儿，烟火冲天。'
  WHEN 1751 THEN '为什么还要心神不定地想去哪里呢？'
  WHEN 1752 THEN '凭什么要飞到九万里的高空再向南飞呢？'
  WHEN 1753 THEN '有一头牛经过堂下，齐王看见它，问道：“牛要到哪里去？”'
  ELSE `example_trans` END
