(1812, 1, '爱', 'ài', '<动>吝惜', '不<b>爱</b>珍器重宝肥饶之地，以致天下之士。', '高中选择性必修中册｜《过秦论》', '不吝惜珍贵器物、重宝和肥沃富饶的土地，来招致天下的士人。', 1, 0),
(1813, 1, '诚', 'chéng', '<副>果真', '<b>诚</b>有百姓者，王无异于百姓之以王为爱也。', '高中必修下册｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(1814, 1, '族', 'zú', '<名>筋骨交错的地方', '每至于<b>族</b>，吾见其难为。', '高中必修下册｜《庖丁解牛》', '每当遇到筋骨交错聚结的地方，我看见它难以处理。', 1, 0),
(1815, 1, '度', 'duó', '<动>估计', '与陈涉<b>度</b>长絜大，比权量力。', '高中选择性必修中册｜《过秦论》', '同陈涉量一量长短、比一比大小，比较一下权势和力量。', 1, 0),
(1816, 1, '举', 'jǔ', '<副>所有', '<b>举</b>天下之豪杰，莫能与之争。', '高中选择性必修中册｜《五代史伶官传序》', '全天下的豪杰，没有人能和他抗争。', 1, 0),
(1817, 1, '安', 'ān', '<使动>使……安定', '知止以<b>安</b>人。', '高中必修下册｜《谏太宗十思疏》', '知道适可而止来使百姓安定。', 1, 0),
(1818, 1, '诚', 'chéng', '<副>确实', '<b>诚</b>宜开张圣听。', '九年级上册｜《出师表》', '确实应当扩大圣明的听闻。', 1, 0),
(1819, 1, '辟', 'pì', '<动>批驳', '<b>辟</b>邪说，难壬人。', '高中必修下册｜《答司马谏议书》', '批驳错误言论，排斥奸佞小人。', 1, 0),
(1820, 1, '诚', 'chéng', '<动>真正，确实', '岂不<b>诚</b>大丈夫哉？', '八年级上册｜《富贵不能淫》', '难道不是真正的大丈夫吗？', 1, 0),
(1821, 1, '举', 'jǔ', '<动>被选拔', '傅说<b>举</b>于版筑之间。', '八年级上册｜《生于忧患，死于安乐》', '傅说从筑墙的劳作中被选拔出来。', 1, 0),
(1822, 1, '诚', 'chéng', '<副>确实，的确', '<b>诚</b>有百姓者，王无异于百姓之以王为爱也。', '高中必修下册｜《谏逐客书》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(1823, 1, '故', 'gù', '<连>所以', '<b>故</b>木受绳则直，金就砺则利。', '高中必修上册｜《劝学》', '所以木材用墨线量过就直，刀剑等金属靠近磨刀石就锋利。', 1, 0),
(1824, 1, '举', 'jǔ', '<动>攻取，占领', '西<b>举</b>巴蜀。', '高中选择性必修中册｜《过秦论》', '向西攻取巴蜀。', 1, 0),
(1825, 1, '举', 'jǔ', '<副>全，所有', '<b>举</b>天下之豪杰。', '高中选择性必修中册｜《五代史伶官传序》', '全天下的豪杰。', 1, 0),
(1826, 1, '故', 'gù', '<连>所以，因此', '<b>故</b>木受绳则直，金就砺则利。', '高中必修上册｜《劝学》', '所以木材用墨线量过就直，刀剑等金属靠近磨刀石就锋利。', 1, 0)
