UPDATE `edu_chn_word_sense` SET
`example` = CASE `id`
  WHEN 1782 THEN '俭以<b>养</b>德。'
  WHEN 1790 THEN '试使山东之国与陈涉<b>度</b>长絜大，比权量力，则不可同年而语矣。'
  WHEN 1822 THEN '<b>诚</b>有百姓者，王无异于百姓之以王为爱也。'
  ELSE `example` END,
`source` = CASE `id`
  WHEN 1782 THEN '七年级上册｜《诫子书》'
  WHEN 1790 THEN '高中选择性必修中册｜《过秦论》'
  WHEN 1822 THEN '高中必修下册｜《齐桓晋文之事》'
  ELSE `source` END,
`example_trans` = CASE `id`
  WHEN 1782 THEN '用节俭来培养品德。'
  WHEN 1790 THEN '假使把崤山以东的国家同陈涉量一量长短、比一比大小，比较一下权势和力量，那就不能相提并论了。'
  WHEN 1822 THEN '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。'
  ELSE `example_trans` END
WHERE `id` IN (1782,1790,1822);

